'use client';

import { useState, useEffect } from 'react';
import { getExpenses, createExpense, deleteExpense, getSalaryReport } from '@/app/actions/expenses';
import { getStaffList } from '@/app/actions/sales';
import { Plus, Trash2, Calendar, User, DollarSign, Tag, Search, Loader2, FileText, Percent, Briefcase, Receipt } from 'lucide-react';
import clsx from 'clsx';

export default function ExpensesPage() {
    const [expenses, setExpenses] = useState<any[]>([]);
    const [users, setUsers] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [salaryMetrics, setSalaryMetrics] = useState({ salaryTotal: 0, nonSalaryTotal: 0, grandTotal: 0, salaryPercent: 0 });

    // New Expense State
    const [showForm, setShowForm] = useState(false);
    const [formData, setFormData] = useState({
        description: '',
        amount: '',
        userId: '',
        category: '',
        date: new Date().toISOString().split('T')[0]
    });

    // Filtering
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [categoryFilter, setCategoryFilter] = useState('ALL');
    const [generatingPdf, setGeneratingPdf] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    async function loadData() {
        setLoading(true);
        const [expData, staff] = await Promise.all([
            getExpenses(dateRange.start, dateRange.end),
            getStaffList()
        ]);
        setExpenses(expData.expenses);
        setSalaryMetrics({
            salaryTotal: expData.salaryTotal,
            nonSalaryTotal: expData.nonSalaryTotal,
            grandTotal: expData.grandTotal,
            salaryPercent: expData.salaryPercent
        });
        setUsers(staff);
        setLoading(false);
    }

    // Refresh when filters change
    useEffect(() => {
        if (!loading) {
            getExpenses(dateRange.start, dateRange.end).then(data => {
                setExpenses(data.expenses);
                setSalaryMetrics({
                    salaryTotal: data.salaryTotal,
                    nonSalaryTotal: data.nonSalaryTotal,
                    grandTotal: data.grandTotal,
                    salaryPercent: data.salaryPercent
                });
            });
        }
    }, [dateRange]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSubmitting(true);
        try {
            const res = await createExpense({
                description: formData.description,
                amount: parseFloat(formData.amount),
                userId: formData.userId,
                category: formData.category,
                date: formData.date
            });
            if (res.success) {
                setShowForm(false);
                setFormData({
                    description: '',
                    amount: '',
                    userId: '',
                    category: '',
                    date: new Date().toISOString().split('T')[0]
                });
                loadData();
            } else {
                alert('Failed to create expense');
            }
        } catch (error) {
            console.error(error);
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this expense?')) return;
        await deleteExpense(id);
        loadData();
    };

    const handleExportSalaryPdf = async () => {
        if (!dateRange.start || !dateRange.end) {
            alert('Please select a date range first to generate salary report.');
            return;
        }
        setGeneratingPdf(true);
        try {
            const report = await getSalaryReport(dateRange.start, dateRange.end);

            // Generate client-side printable report
            const printWindow = window.open('', '_blank');
            if (!printWindow) return;

            const html = `<!DOCTYPE html>
<html dir="rtl"><head><meta charset="utf-8"><title>Salary Report</title>
<style>
    body { font-family: 'Segoe UI', Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 40px; }
    h1 { text-align: center; border-bottom: 3px solid #333; padding-bottom: 10px; }
    .period { text-align: center; color: #666; margin-bottom: 30px; }
    .summary { background: #f4f4f4; padding: 20px; border-radius: 8px; margin-bottom: 30px; display: flex; justify-content: space-between; }
    .summary-item { text-align: center; }
    .summary-item .value { font-size: 24px; font-weight: bold; color: #1a1a1a; }
    .summary-item .label { font-size: 12px; color: #666; text-transform: uppercase; }
    .employee { margin-bottom: 20px; border: 1px solid #ddd; border-radius: 8px; overflow: hidden; }
    .employee-header { background: #333; color: white; padding: 12px 16px; display: flex; justify-content: space-between; }
    .employee-entries { padding: 0; }
    .entry { display: flex; justify-content: space-between; padding: 10px 16px; border-bottom: 1px solid #eee; }
    .entry:last-child { border-bottom: none; }
    @media print { body { padding: 20px; } }
</style></head><body>
<h1>📋 Salary Expense Report</h1>
<div class="period">Period: ${report.period.startDate} to ${report.period.endDate}</div>
<div class="summary">
    <div class="summary-item"><div class="value">EGP ${report.grandTotal.toLocaleString()}</div><div class="label">Total Salaries</div></div>
    <div class="summary-item"><div class="value">${report.employees.length}</div><div class="label">Employees</div></div>
</div>
${report.employees.map(emp => `
<div class="employee">
    <div class="employee-header">
        <span>${emp.name}</span>
        <span>EGP ${emp.total.toLocaleString()}</span>
    </div>
    <div class="employee-entries">
        ${emp.entries.map(e => `<div class="entry"><span>${new Date(e.date).toLocaleDateString()}</span><span>${e.description}</span><span style="font-weight:bold">EGP ${e.amount.toLocaleString()}</span></div>`).join('')}
    </div>
</div>`).join('')}
</body></html>`;

            printWindow.document.write(html);
            printWindow.document.close();
            printWindow.focus();
            setTimeout(() => printWindow.print(), 500);
        } catch (err) {
            console.error(err);
            alert('Failed to generate report');
        } finally {
            setGeneratingPdf(false);
        }
    };

    // Filter by category on client-side
    const filteredExpenses = categoryFilter === 'ALL'
        ? expenses
        : categoryFilter === 'SALARY'
            ? expenses.filter(e => e.category?.toUpperCase() === 'SALARY')
            : expenses.filter(e => e.category?.toUpperCase() !== 'SALARY');

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
                        <Receipt className="text-primary" />
                        المصروفات
                    </h1>
                    <p className="text-muted-foreground">Expenses & Salary Tracking</p>
                </div>
            </div>

            {/* Metrics Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-primary/10 rounded-lg text-primary"><DollarSign size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Total Spend</span>
                    </div>
                    <div className="text-2xl font-black">EGP {salaryMetrics.grandTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-blue-500/10 rounded-lg text-blue-500"><Briefcase size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Salary Total</span>
                    </div>
                    <div className="text-2xl font-black text-blue-600">EGP {salaryMetrics.salaryTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500"><Tag size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Other Expenses</span>
                    </div>
                    <div className="text-2xl font-black text-orange-600">EGP {salaryMetrics.nonSalaryTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-purple-500/10 rounded-lg text-purple-500"><Percent size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Salary %</span>
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-2xl font-black text-purple-600">{salaryMetrics.salaryPercent}%</span>
                        <div className="flex-1 h-2 bg-secondary rounded-full overflow-hidden mb-1">
                            <div className="h-full bg-purple-500 rounded-full transition-all" style={{ width: `${salaryMetrics.salaryPercent}%` }} />
                        </div>
                    </div>
                </div>
            </div>

            {/* Controls */}
            <div className="flex flex-wrap items-center gap-4 bg-card p-4 rounded-xl border border-border">
                <div className="flex items-center gap-2">
                    <input
                        type="date"
                        value={dateRange.start}
                        onChange={e => setDateRange({ ...dateRange, start: e.target.value })}
                        className="bg-background border border-border rounded-lg p-2 text-sm"
                    />
                    <span className="text-muted-foreground">-</span>
                    <input
                        type="date"
                        value={dateRange.end}
                        onChange={e => setDateRange({ ...dateRange, end: e.target.value })}
                        className="bg-background border border-border rounded-lg p-2 text-sm"
                    />
                </div>

                <select
                    value={categoryFilter}
                    onChange={(e) => setCategoryFilter(e.target.value)}
                    className="px-3 py-2 bg-background border border-input rounded-lg text-sm"
                >
                    <option value="ALL">All Categories</option>
                    <option value="SALARY">Salaries Only</option>
                    <option value="OTHER">Non-Salary Only</option>
                </select>

                <div className="ml-auto flex items-center gap-2">
                    <button
                        onClick={handleExportSalaryPdf}
                        disabled={generatingPdf}
                        className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors text-sm font-medium disabled:opacity-50"
                    >
                        {generatingPdf ? <Loader2 className="animate-spin" size={16} /> : <FileText size={16} />}
                        Salary PDF
                    </button>
                    <button
                        onClick={() => setShowForm(!showForm)}
                        className="flex items-center gap-2 bg-primary text-primary-foreground px-4 py-2 rounded-lg font-bold hover:bg-primary/90 transition-colors"
                    >
                        <Plus size={18} />
                        New Expense
                    </button>
                </div>
            </div>

            {/* Form */}
            {showForm && (
                <div className="bg-card border border-border p-6 rounded-xl animate-in slide-in-from-top-2 shadow-lg">
                    <h3 className="text-lg font-bold mb-4">Add New Expense</h3>
                    <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Description</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Tag size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    placeholder="Make coffee, electricity..."
                                    value={formData.description}
                                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Amount (EGP)</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <DollarSign size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    type="number"
                                    min="0"
                                    step="0.01"
                                    placeholder="0.00"
                                    value={formData.amount}
                                    onChange={e => setFormData({ ...formData, amount: e.target.value })}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Who Spent?</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <User size={16} className="text-muted-foreground" />
                                <select
                                    required
                                    value={formData.userId}
                                    onChange={e => setFormData({ ...formData, userId: e.target.value })}
                                    className="flex-1 bg-transparent outline-none text-sm cursor-pointer"
                                >
                                    <option value="">Select Staff...</option>
                                    {users.map(u => (
                                        <option key={u.id} value={u.id}>{u.name || u.username}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Category</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Search size={16} className="text-muted-foreground" />
                                <select
                                    value={formData.category}
                                    onChange={e => setFormData({ ...formData, category: e.target.value })}
                                    className="flex-1 bg-transparent outline-none text-sm cursor-pointer"
                                >
                                    <option value="">Select Category...</option>
                                    <option value="SALARY">💰 Salary</option>
                                    <option value="Utilities">⚡ Utilities</option>
                                    <option value="Supplies">📦 Supplies</option>
                                    <option value="Maintenance">🔧 Maintenance</option>
                                    <option value="Other">📋 Other</option>
                                </select>
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Date</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Calendar size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    type="date"
                                    value={formData.date}
                                    onChange={e => setFormData({ ...formData, date: e.target.value })}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="flex items-end">
                            <button
                                disabled={submitting}
                                className="w-full bg-primary text-primary-foreground p-2 rounded-lg font-bold hover:bg-primary/90 transition-colors flex items-center justify-center gap-2"
                            >
                                {submitting ? <Loader2 className="animate-spin" /> : 'Save Expense'}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* List */}
            <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-secondary/20 font-bold text-muted-foreground border-b border-border">
                            <tr>
                                <th className="px-4 py-3 text-left">Date</th>
                                <th className="px-4 py-3 text-left">Description</th>
                                <th className="px-4 py-3 text-left">Category</th>
                                <th className="px-4 py-3 text-left">Spent By</th>
                                <th className="px-4 py-3 text-right">Amount</th>
                                <th className="px-4 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border/50">
                            {loading ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-muted-foreground">
                                        <Loader2 className="animate-spin mx-auto mb-2" /> Loading expenses...
                                    </td>
                                </tr>
                            ) : filteredExpenses.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-muted-foreground">No expenses found for this period.</td>
                                </tr>
                            ) : (
                                filteredExpenses.map(exp => (
                                    <tr key={exp.id} className="hover:bg-secondary/10 transition-colors">
                                        <td className="px-4 py-3">{new Date(exp.date).toLocaleDateString()}</td>
                                        <td className="px-4 py-3 font-medium">{exp.description}</td>
                                        <td className="px-4 py-3">
                                            {exp.category && (
                                                <span className={clsx(
                                                    "px-2 py-1 rounded text-xs font-bold",
                                                    exp.category?.toUpperCase() === 'SALARY' ? "bg-blue-100 text-blue-700" : "bg-secondary text-foreground"
                                                )}>
                                                    {exp.category?.toUpperCase() === 'SALARY' ? '💰 ' : ''}{exp.category}
                                                </span>
                                            )}
                                        </td>
                                        <td className="px-4 py-3">{exp.userName}</td>
                                        <td className="px-4 py-3 text-right font-bold text-red-600">-EGP {exp.amount.toLocaleString()}</td>
                                        <td className="px-4 py-3 text-right">
                                            <button
                                                onClick={() => handleDelete(exp.id)}
                                                className="text-muted-foreground hover:text-red-500 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Truck, Plus, Loader2, X, Check } from 'lucide-react';
import { getIncomingTransactions, getLocations, createIncomingStock } from '@/app/actions/incoming';
import { getProducts } from '@/app/actions/sales';

interface IncomingItem {
    id: string;
    productName: string;
    quantity: number;
    supplier: string;
    costPrice: number;
    status: 'pending' | 'received' | 'rejected';
    date?: Date;
}

export default function IncomingStockPage() {
    const [items, setItems] = useState<IncomingItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // Form State
    const [products, setProducts] = useState<any[]>([]);
    const [locations, setLocations] = useState<any[]>([]);
    const [formData, setFormData] = useState({
        productId: '',
        quantity: 1,
        locationId: '',
        notes: ''
    });

    const refreshData = async () => {
        setLoading(true);
        const data = await getIncomingTransactions();
        setItems(data as IncomingItem[]);
        setLoading(false);
    };

    useEffect(() => {
        refreshData();
        // Pre-fetch products and locations
        getProducts().then(setProducts);
        getLocations().then(setLocations);
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.productId || !formData.locationId || formData.quantity <= 0) return;

        setSubmitting(true);
        try {
            await createIncomingStock(formData);
            await refreshData();
            setIsModalOpen(false);
            setFormData({ productId: '', quantity: 1, locationId: '', notes: '' });
        } catch (error) {
            console.error("Failed to add purchase:", error);
            alert("Failed to add purchase. Please check connection.");
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <h2 className="text-3xl font-bold tracking-tight">Incoming Stock</h2>
                <button
                    onClick={() => setIsModalOpen(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg transition-all shadow-sm active:scale-95"
                >
                    <Plus size={16} />
                    New Purchase Order
                </button>
            </div>

            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                <div className="bg-card p-6 rounded-xl border border-border shadow-sm group hover:border-primary/50 transition-colors">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-100 text-blue-700 rounded-xl dark:bg-blue-900/30 dark:text-blue-300 group-hover:scale-110 transition-transform">
                            <Truck size={24} />
                        </div>
                        <div>
                            <div className="text-sm font-medium text-muted-foreground uppercase tracking-wider">Total Shipments</div>
                            <div className="text-2xl font-bold">{items.length} Records</div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                            <tr>
                                <th className="px-6 py-4 uppercase tracking-wider">Product</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Quantity</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Supplier / Notes</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Total Cost</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Date</th>
                                <th className="px-6 py-4 uppercase tracking-wider text-right">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {loading ? (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">
                                        <div className="flex flex-col items-center justify-center gap-3">
                                            <Loader2 className="animate-spin text-primary" size={32} />
                                            <span className="animate-pulse">Loading shipments...</span>
                                        </div>
                                    </td>
                                </tr>
                            ) : items.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">
                                        <div className="flex flex-col items-center gap-2">
                                            <Truck size={40} className="mb-2 opacity-20" />
                                            <p className="text-lg font-medium">No incoming stock history.</p>
                                            <p className="text-sm opacity-60">Create a purchase order to populate this list.</p>
                                        </div>
                                    </td>
                                </tr>
                            ) : (
                                items.map(item => (
                                    <tr key={item.id} className="hover:bg-muted/50 transition-colors">
                                        <td className="px-6 py-4 font-semibold text-foreground">{item.productName}</td>
                                        <td className="px-6 py-4 font-medium">{item.quantity}</td>
                                        <td className="px-6 py-4 text-muted-foreground truncate max-w-[200px]">{item.supplier}</td>
                                        <td className="px-6 py-4 font-bold text-primary">EGP {item.costPrice.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-muted-foreground">{item.date ? new Date(item.date).toLocaleDateString() : '-'}</td>
                                        <td className="px-6 py-4 text-right">
                                            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300">
                                                <Check size={10} />
                                                {item.status}
                                            </span>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modal Overlay */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-2xl border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-secondary/20">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <Plus className="text-primary" size={20} />
                                New Purchase Order
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-1 hover:bg-secondary rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div className="space-y-2">
                                <label className="text-sm font-semibold text-muted-foreground">Select Product</label>
                                <select
                                    className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                    required
                                    value={formData.productId}
                                    onChange={(e) => setFormData({ ...formData, productId: e.target.value })}
                                >
                                    <option value="">Choose item...</option>
                                    {products.map(p => (
                                        <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-semibold text-muted-foreground">Quantity</label>
                                    <input
                                        type="number"
                                        min="1"
                                        className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                        required
                                        value={formData.quantity}
                                        onChange={(e) => setFormData({ ...formData, quantity: parseInt(e.target.value) })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-semibold text-muted-foreground">Target Location</label>
                                    <select
                                        className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                        required
                                        value={formData.locationId}
                                        onChange={(e) => setFormData({ ...formData, locationId: e.target.value })}
                                    >
                                        <option value="">Select branch...</option>
                                        {locations.map(l => (
                                            <option key={l.id} value={l.id}>{l.name}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-semibold text-muted-foreground">Supplier / Notes</label>
                                <textarea
                                    className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all resize-none h-24"
                                    placeholder="Enter supplier name or delivery notes..."
                                    value={formData.notes}
                                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                />
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setIsModalOpen(false)}
                                    className="flex-1 px-4 py-3 rounded-xl border border-border hover:bg-secondary font-semibold transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="flex-1 px-4 py-3 rounded-xl bg-primary text-primary-foreground font-bold hover:bg-primary/90 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-lg shadow-primary/20"
                                >
                                    {submitting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}
                                    Add Purchase
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { getInvoiceById } from '@/app/actions/invoices';
import { Loader2, Printer, Settings2, Edit3, X, ChevronDown, ChevronUp } from 'lucide-react';
import { tafqeet } from '@/lib/tafqeet';

export default function InvoicePrintPage() {
    const { id } = useParams();
    const [invoice, setInvoice] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [showSettings, setShowSettings] = useState(true);

    // Editable Data States
    const [warehouseName, setWarehouseName] = useState("المخزن الرئيسي");
    const [city, setCity] = useState("كفر الشيخ");
    const [category, setCategory] = useState("عاملين");
    const [phone1, setPhone1] = useState("");
    const [phone2, setPhone2] = useState("");
    const [sequenceId, setSequenceId] = useState("");
    const [customerCode, setCustomerCode] = useState("");
    const [employeeId, setEmployeeId] = useState("");
    const [employeeName, setEmployeeName] = useState("");
    const [address, setAddress] = useState("");
    const [customerName, setCustomerName] = useState("");

    useEffect(() => {
        if (id) {
            getInvoiceById(id as string).then(data => {
                setInvoice(data);
                if (data) {
                    setSequenceId(parseInt(data.id.slice(-4), 16).toString());
                    setCustomerCode("01/1/3/" + parseInt(data.id.slice(0, 3), 16));
                    setEmployeeName(data.user?.name || data.user?.username || "Unknown");
                    setEmployeeId(data.user?.id ? parseInt(data.user.id.slice(0, 2), 16).toString() : "5");
                    setAddress(data.customerAddress || "");
                    setPhone1(data.customerPhone || "");
                    setCustomerName(data.customerName || "عميل نقدي");
                }
                setLoading(false);
            });
        }
    }, [id]);

    if (loading) {
        return (
            <div className="flex h-screen items-center justify-center bg-gray-50">
                <div className="flex flex-col items-center gap-4 text-blue-600">
                    <Loader2 className="animate-spin" size={40} />
                    <p className="font-bold">جاري تحميل الفاتورة...</p>
                </div>
            </div>
        );
    }

    if (!invoice) {
        return (
            <div className="flex h-screen items-center justify-center bg-gray-50">
                <div className="bg-white p-10 rounded-2xl shadow-xl text-center">
                    <p className="font-bold text-red-500 text-xl mb-2">الفاتورة غير موجودة</p>
                    <p className="text-gray-500">تأكد من الرابط وحاول مرة أخرى.</p>
                </div>
            </div>
        );
    }

    const formattedDate = new Date(invoice.date).toLocaleDateString('en-GB');

    return (
        <div className="min-h-screen bg-gray-100 flex flex-col md:flex-row print:block" dir="rtl">
            {/* Print Styles Injection */}
            <style jsx global>{`
                @media print {
                    @page { size: A4; margin: 10mm; }
                    body { -webkit-print-color-adjust: exact; background: white !important; }
                    header, footer, nav, aside { display: none !important; }
                    .print-hidden { display: none !important; }
                    .print-shadow-none { shadow: none !important; border-color: #000 !important; }
                }
            `}</style>

            {/* --- SETTINGS SIDEBAR (Hidden on Print) --- */}
            <div className={`print-hidden bg-white border-l border-gray-200 shadow-xl transition-all duration-300 flex flex-col z-10 ${showSettings ? 'w-full md:w-80 h-auto md:h-screen sticky top-0' : 'w-full md:w-16 h-auto md:h-screen sticky top-0'}`}>
                <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-blue-50/50">
                    {showSettings && <h2 className="font-bold text-blue-900 flex items-center gap-2"><Settings2 size={18} /> إعدادات الطباعة</h2>}
                    <button 
                        onClick={() => setShowSettings(!showSettings)} 
                        className="p-2 hover:bg-blue-100 rounded-lg text-blue-700 transition-colors mx-auto md:mx-0"
                        title={showSettings ? "إخفاء" : "إظهار"}
                    >
                        {showSettings ? <X size={20} className="hidden md:block" /> : <Settings2 size={20} />}
                        <span className="md:hidden text-sm font-bold flex items-center gap-1">
                            {showSettings ? <ChevronUp size={16}/> : <ChevronDown size={16}/>} 
                            {showSettings ? 'إخفاء الإعدادات' : 'إظهار الإعدادات'}
                        </span>
                    </button>
                </div>

                {showSettings && (
                    <div className="p-5 overflow-y-auto flex-1 space-y-4">
                        <div className="space-y-3">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">بيانات الفاتورة</h3>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">الرقم المرجعي</label>
                                <input type="text" value={sequenceId} onChange={e => setSequenceId(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">المخزن / المستودع</label>
                                <input type="text" value={warehouseName} onChange={e => setWarehouseName(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                            </div>
                        </div>

                        <div className="border-t border-gray-100 pt-4 space-y-3">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">بيانات العميل</h3>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">اسم العميل</label>
                                <input type="text" value={customerName} onChange={e => setCustomerName(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">كود العميل</label>
                                <input type="text" value={customerCode} onChange={e => setCustomerCode(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-xs font-medium text-gray-700 mb-1">المدينة</label>
                                    <input type="text" value={city} onChange={e => setCity(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                                <div>
                                    <label className="block text-xs font-medium text-gray-700 mb-1">الفئة</label>
                                    <input type="text" value={category} onChange={e => setCategory(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">العنوان</label>
                                <input type="text" value={address} onChange={e => setAddress(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-xs font-medium text-gray-700 mb-1">رقم الهاتف 1</label>
                                    <input type="text" value={phone1} onChange={e => setPhone1(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                                <div>
                                    <label className="block text-xs font-medium text-gray-700 mb-1">رقم الهاتف 2</label>
                                    <input type="text" value={phone2} onChange={e => setPhone2(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                            </div>
                        </div>

                        <div className="border-t border-gray-100 pt-4 space-y-3">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">بيانات الموظف</h3>
                            <div className="grid grid-cols-3 gap-2">
                                <div className="col-span-1">
                                    <label className="block text-xs font-medium text-gray-700 mb-1">الرقم</label>
                                    <input type="text" value={employeeId} onChange={e => setEmployeeId(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                                <div className="col-span-2">
                                    <label className="block text-xs font-medium text-gray-700 mb-1">الاسم</label>
                                    <input type="text" value={employeeName} onChange={e => setEmployeeName(e.target.value)} className="w-full text-sm p-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                            </div>
                        </div>

                        <div className="border-t border-gray-100 pt-6 pb-8">
                            <button
                                onClick={() => window.print()}
                                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded-xl shadow-[0_4px_14px_rgba(37,99,235,0.3)] transition-all flex justify-center items-center gap-2"
                            >
                                <Printer size={20} />
                                <span>طباعة الفاتورة</span>
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* --- INVOICE PAPER --- */}
            <div className="flex-1 p-4 md:p-8 overflow-y-auto">
                <div className="max-w-[210mm] mx-auto bg-white print-shadow-none shadow-2xl rounded-sm p-[10mm] min-h-[297mm] border border-gray-200 text-black">
                    
                    {/* Header */}
                    <div className="flex justify-between items-start mb-6 border-b-2 border-gray-900 pb-6">
                        {/* Company Logo / Name Area */}
                        <div className="flex-1">
                            <h1 className="text-3xl font-black text-gray-900 mb-1 tracking-tight">شركة المبيعات</h1>
                            <p className="text-gray-500 font-medium text-sm">نظام إدارة المبيعات المتكامل</p>
                            <div className="mt-4 flex items-center gap-2">
                                <span className="bg-gray-100 text-gray-800 px-3 py-1 rounded font-bold text-sm border border-gray-200">
                                    المستودع: {warehouseName}
                                </span>
                            </div>
                        </div>

                        {/* Title */}
                        <div className="flex-1 text-center flex flex-col items-center justify-center">
                            <div className="border-4 border-gray-900 px-6 py-2 uppercase tracking-widest text-xl font-black rounded-lg transform -rotate-2">
                                فاتورة مبيعات
                            </div>
                        </div>

                        {/* Invoice Meta */}
                        <div className="flex-1 flex justify-end">
                            <table className="text-sm border-collapse border border-gray-300 font-medium bg-gray-50">
                                <tbody>
                                    <tr>
                                        <td className="border border-gray-300 px-3 py-1 bg-gray-100 text-gray-700 font-bold">الرقم</td>
                                        <td className="border border-gray-300 px-3 py-1 text-center font-bold text-lg">{sequenceId}</td>
                                    </tr>
                                    <tr>
                                        <td className="border border-gray-300 px-3 py-1 bg-gray-100 text-gray-700 font-bold">التاريخ</td>
                                        <td className="border border-gray-300 px-3 py-1 text-center">{formattedDate}</td>
                                    </tr>
                                    <tr>
                                        <td className="border border-gray-300 px-3 py-1 bg-gray-100 text-gray-700 font-bold">الموظف</td>
                                        <td className="border border-gray-300 px-3 py-1 text-center">
                                            <span className="font-bold">{employeeId}</span> - {employeeName}
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Customer Info Section */}
                    <div className="mb-6 rounded-lg border border-gray-300 overflow-hidden bg-gray-50/50">
                        <div className="bg-gray-100 border-b border-gray-300 px-4 py-2 font-bold text-gray-800 flex items-center justify-between">
                            <span>بيانات العميل</span>
                            <span className="text-xs font-mono bg-white px-2 py-0.5 rounded border border-gray-200">{customerCode}</span>
                        </div>
                        <div className="p-4">
                            <div className="grid grid-cols-12 gap-y-3 gap-x-4 text-sm">
                                <div className="col-span-12 md:col-span-6 flex gap-2">
                                    <span className="font-bold text-gray-600 w-20 shrink-0">اسم العميل:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{customerName}</span>
                                </div>
                                <div className="col-span-12 md:col-span-3 flex gap-2">
                                    <span className="font-bold text-gray-600 w-16 shrink-0">المدينة:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{city}</span>
                                </div>
                                <div className="col-span-12 md:col-span-3 flex gap-2">
                                    <span className="font-bold text-gray-600 w-12 shrink-0">الفئة:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{category}</span>
                                </div>

                                <div className="col-span-12 md:col-span-6 flex gap-2">
                                    <span className="font-bold text-gray-600 w-20 shrink-0">العنوان:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{address}</span>
                                </div>
                                <div className="col-span-12 md:col-span-3 flex gap-2">
                                    <span className="font-bold text-gray-600 w-16 shrink-0">هاتف 1:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{phone1}</span>
                                </div>
                                <div className="col-span-12 md:col-span-3 flex gap-2">
                                    <span className="font-bold text-gray-600 w-12 shrink-0">هاتف 2:</span>
                                    <span className="font-bold text-gray-900 border-b border-gray-300 flex-1 pb-1">{phone2}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Line Items */}
                    <div className="min-h-[200px]">
                        <table className="w-full border-collapse border-2 border-gray-900 text-sm">
                            <thead>
                                <tr className="bg-gray-100 border-b-2 border-gray-900 text-gray-800">
                                    <th className="border-l border-gray-300 py-2 w-10 text-center">م</th>
                                    <th className="border-l border-gray-300 py-2 w-24 text-center">رقم الصنف</th>
                                    <th className="border-l border-gray-300 py-2 px-3 text-right">اسم الصنف</th>
                                    <th className="border-l border-gray-300 py-2 w-16 text-center">الوحدة</th>
                                    <th className="border-l border-gray-300 py-2 w-16 text-center">الكمية</th>
                                    <th className="border-l border-gray-300 py-2 w-20 text-center">السعر</th>
                                    <th className="border-l border-gray-300 py-2 w-16 text-center">ن الخصم</th>
                                    <th className="border-l border-gray-300 py-2 w-16 text-center">ق الخصم</th>
                                    <th className="py-2 w-24 text-center font-bold">القيمة</th>
                                </tr>
                            </thead>
                            <tbody>
                                {invoice.items.map((item: any, idx: number) => (
                                    <tr key={idx} className="border-b border-gray-300 even:bg-gray-50/50">
                                        <td className="border-l border-gray-300 py-2 text-center text-gray-500 font-medium">{idx + 1}</td>
                                        <td className="border-l border-gray-300 py-2 text-center font-mono text-gray-600">{item.productCode || '---'}</td>
                                        <td className="border-l border-gray-300 py-2 px-3 font-bold text-gray-900 text-right">{item.productName}</td>
                                        <td className="border-l border-gray-300 py-2 text-center text-gray-600">{item.productUnit || 'قطعة'}</td>
                                        <td className="border-l border-gray-300 py-2 text-center font-bold">{item.quantity}</td>
                                        <td className="border-l border-gray-300 py-2 text-center font-medium">{item.unitPrice.toFixed(2)}</td>
                                        <td className="border-l border-gray-300 py-2 text-center text-gray-400">-</td>
                                        <td className="border-l border-gray-300 py-2 text-center text-gray-400">-</td>
                                        <td className="py-2 text-center font-bold text-gray-900 bg-gray-50/80">{item.subtotal.toFixed(2)}</td>
                                    </tr>
                                ))}
                                {/* Empty spacer row if needed to push footer down could be added here */}
                            </tbody>
                        </table>
                    </div>

                    {/* Footer Totals & Financials */}
                    <div className="mt-6 flex flex-col md:flex-row gap-6">
                        {/* Summary & Word Amount */}
                        <div className="flex-1 flex flex-col justify-between space-y-4">
                            <div className="flex gap-6 items-center bg-gray-50 border border-gray-300 p-3 rounded-lg">
                                <div className="flex-1 flex items-center justify-between border-l border-gray-300 pl-4">
                                    <span className="font-bold text-gray-700">إجمالي الكمية</span>
                                    <span className="font-black text-xl text-gray-900 bg-white px-3 py-1 rounded border border-gray-200">
                                        {invoice.items.reduce((acc: number, item: any) => acc + item.quantity, 0)}
                                    </span>
                                </div>
                                <div className="flex-1 flex items-center justify-between">
                                    <span className="font-bold text-gray-700">الإجمالي العام</span>
                                    <span className="font-black text-2xl text-gray-900 bg-white px-3 py-1 rounded border border-gray-200">
                                        {invoice.totalAmount.toFixed(2)}
                                    </span>
                                </div>
                            </div>

                            <div className="border border-gray-800 p-3 text-center rounded bg-white relative">
                                <span className="absolute -top-3 right-4 bg-white px-2 text-xs font-bold text-gray-500">المبلغ بالحروف</span>
                                <p className="font-bold text-gray-900 text-lg leading-relaxed">
                                    فقط وقدره ( {tafqeet(Number(invoice.totalAmount))} ) لا غير.
                                </p>
                            </div>
                        </div>

                        {/* Financial Balances */}
                        <div className="w-full md:w-72 border-2 border-gray-900 rounded-lg overflow-hidden bg-white">
                            <div className="bg-gray-900 text-white text-center py-1 font-bold text-sm tracking-widest">
                                كشف الحساب
                            </div>
                            <div className="grid grid-cols-2 text-sm divide-x divide-x-reverse divide-gray-200">
                                <div className="bg-gray-100 p-2 font-bold text-gray-700">الرصيد السابق</div>
                                <div className="p-2 font-black text-center">{Number(invoice.previousBalance || 0).toLocaleString()}</div>

                                <div className="bg-gray-100 p-2 font-bold text-gray-700 border-t border-gray-200">قيمة الفاتورة</div>
                                <div className="p-2 font-black text-center border-t border-gray-200 text-blue-700">{Number(invoice.totalAmount).toLocaleString()}</div>

                                <div className="bg-gray-100 p-2 font-bold text-gray-700 border-t border-gray-200 flex flex-col justify-center">
                                    <span>المدفوع</span>
                                    <span className="text-[10px] font-normal text-gray-500">{invoice.paymentMethod === 'CREDIT' ? 'آجل' : 'نقداً'}</span>
                                </div>
                                <div className="p-2 font-black text-center border-t border-gray-200 text-green-600 flex items-center justify-center">
                                    {Number(invoice.amountPaid || 0).toLocaleString()}
                                </div>

                                <div className="bg-gray-200 p-2 font-black text-gray-900 border-t border-gray-300">الرصيد المتبقي</div>
                                <div className="p-2 font-black text-center text-xl border-t border-gray-300 bg-gray-50 text-red-600">
                                    {Number(invoice.currentBalance || 0).toLocaleString()}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Signatures */}
                    <div className="mt-12 flex justify-between px-16 text-lg font-bold">
                        <div className="text-center w-40 flex flex-col items-center">
                            <div className="h-12 border-b-2 border-dashed border-gray-400 w-full mb-2"></div>
                            <span className="text-gray-600 text-sm">توقيع المستلم</span>
                        </div>
                        <div className="text-center w-40 flex flex-col items-center">
                            <div className="h-12 border-b-2 border-dashed border-gray-400 w-full mb-2"></div>
                            <span className="text-gray-600 text-sm">توقيع المسئول</span>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { FileText, Download, Filter, Search, Calendar, Loader2, X, Printer, RefreshCcw } from 'lucide-react';
import { getInvoices } from '@/app/actions/invoices';
import { printElement } from '@/components/ui/PrintExport';
import RefundModal from '@/components/RefundModal';

interface Invoice {
    id: string;
    customerName: string | null;
    customerPhone: string | null;
    customerAddress: string | null;
    user?: {
        id: string;
        name: string | null;
        username: string;
        phone: string | null;
        address: string | null;
    };
    date: Date;
    totalAmount: number;
    paymentMethod: string;
    previousBalance?: number;
    amountPaid?: number;
    currentBalance?: number;
    items?: Array<{
        id: string;
        productId: string;
        product: { name: string, sku: string };
        quantity: number;
        refundableQuantity: number;
        unitPrice: number;
        subtotal: number;
    }>;
}

export default function InvoicesPage() {
    const [invoices, setInvoices] = useState<Invoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
    const [showRefundModal, setShowRefundModal] = useState(false);

    // Date Filter State
    const [showDateFilter, setShowDateFilter] = useState(false);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        getInvoices().then(data => {
            // Map Prisma result to UI interface if needed, currently straightforward
            // But we need to handle the types correctly
            setInvoices(data as any); // Casting for now as getInvoices returns mapped objects
            setLoading(false);
        });
    }, []);

    const handleDownload = (invoice: Invoice) => {
        // We defer the print call slightly to ensure the modal content is rendered if we are opening it just for print
        // But here we assume modal is open or we print the currently selected one
        setTimeout(() => {
            printElement(
                `Invoice #${invoice.id.slice(0, 8).toUpperCase()}`,
                'print-invoice-content',
                `<p>Customer: ${invoice.customerName || 'Walk-in'}</p>`
            );
        }, 100);
    }

    const handlePrintReport = () => {
        const dateRangeStr = startDate || endDate ? `<p>Period: ${startDate || 'Start'} to ${endDate || 'Now'}</p>` : '';
        printElement('Invoices Report', 'print-invoice-list', dateRangeStr);
    };

    const filteredInvoices = invoices.filter(inv => {
        const query = searchQuery.toLowerCase();
        const matchesSearch = (
            inv.id.toLowerCase().includes(query) ||
            (inv.customerName && inv.customerName.toLowerCase().includes(query)) ||
            (inv.user?.username && inv.user.username.toLowerCase().includes(query))
        );

        const invDate = new Date(inv.date);
        const matchesDate =
            (!startDate || invDate >= new Date(startDate)) &&
            (!endDate || invDate <= new Date(new Date(endDate).setHours(23, 59, 59)));

        return matchesSearch && matchesDate;
    });



    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <h2 className="text-3xl font-bold tracking-tight">Invoices</h2>
                <div className="flex gap-2">
                    <button
                        onClick={() => setShowDateFilter(!showDateFilter)}
                        className={`flex items-center gap-2 px-4 py-2 border rounded-lg transition-colors ${showDateFilter ? 'bg-secondary border-primary' : 'border-border hover:bg-secondary'}`}
                    >
                        <Calendar size={16} />
                        Date Range
                    </button>
                    <button
                        onClick={handlePrintReport}
                        className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg"
                    >
                        <Printer size={16} />
                        Export Report
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-4 bg-card p-4 rounded-xl border border-border">
                <Search className="text-muted-foreground" size={18} />
                <input
                    placeholder="Search invoice # or customer..."
                    className="flex-1 bg-transparent outline-none"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                />
                <button className="p-2 hover:bg-secondary rounded">
                    <Filter size={18} />
                </button>
            </div>

            {/* Date Range Inputs */}
            {showDateFilter && (
                <div className="flex flex-wrap items-center gap-4 p-4 bg-secondary/20 rounded-xl border border-border animate-in slide-in-from-top-2">
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">From:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">To:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <button
                        onClick={() => { setStartDate(''); setEndDate(''); }}
                        className="text-xs text-muted-foreground hover:text-primary transition-colors underline"
                    >
                        Clear Filter
                    </button>
                </div>
            )}

            {/* List */}
            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center p-8 text-muted-foreground">
                        <Loader2 className="animate-spin mr-2" /> Loading invoices...
                    </div>
                ) : filteredInvoices.length === 0 ? (
                    <div className="text-center p-8 text-muted-foreground">No invoices found.</div>
                ) : (
                    filteredInvoices.map(inv => (
                        <div
                            key={inv.id}
                            onClick={() => setSelectedInvoice(inv)}
                            className="flex flex-col md:flex-row md:items-center justify-between p-4 bg-card border border-border rounded-xl hover:shadow-md transition-shadow cursor-pointer group gap-4"
                        >
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-secondary/50 rounded-lg text-primary group-hover:scale-110 transition-transform">
                                    <FileText size={24} />
                                </div>
                                <div>
                                    <div className="font-bold">
                                        {inv.customerName || (inv.user ? `${inv.user.username}` : 'Walk-in Customer')}
                                    </div>
                                    <div className="text-sm text-muted-foreground flex gap-2">
                                        <span className="font-mono">#{inv.id.slice(0, 8).toUpperCase()}</span>
                                        <span>•</span>
                                        <span>{new Date(inv.date).toLocaleDateString()}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-4 md:gap-8 justify-between md:justify-end w-full md:w-auto">
                                <div className="text-right">
                                    <div className="font-bold text-lg">EGP {Number(inv.totalAmount).toLocaleString()}</div>
                                    <div className="text-xs text-muted-foreground">{inv.paymentMethod}</div>
                                </div>

                                <div className="px-3 py-1 rounded-full text-xs font-bold uppercase bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300">
                                    Paid
                                </div>

                                <button
                                    onClick={(e) => { e.stopPropagation(); setSelectedInvoice(inv); handleDownload(inv); }}
                                    className="p-2 hover:bg-secondary rounded-full text-muted-foreground hover:text-foreground transition-colors"
                                    title="Print / Download PDF"
                                >
                                    <Printer size={20} />
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Details Modal */}
            {selectedInvoice && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-2xl rounded-2xl border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-secondary/10">
                            <div>
                                <h3 className="text-xl font-bold flex items-center gap-2">
                                    Invoice Details
                                </h3>
                                <p className="text-xs text-muted-foreground font-mono mt-1">ID: {selectedInvoice.id}</p>
                            </div>
                            <button onClick={() => setSelectedInvoice(null)} className="p-2 hover:bg-secondary rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <div id="print-invoice-content" className="flex-1 overflow-y-auto p-6 space-y-6">
                            {/* Summary Header */}
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-muted/20 rounded-xl border border-border">
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Date & Time</label>
                                    <div className="text-sm font-semibold">{new Date(selectedInvoice.date).toLocaleString()}</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Payment</label>
                                    <div className="text-sm font-semibold">{selectedInvoice.paymentMethod}</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Status</label>
                                    <div className="text-sm font-bold text-green-500">PAID</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Invoice #</label>
                                    <div className="text-sm font-mono">{selectedInvoice.id.slice(0, 8).toUpperCase()}</div>
                                </div>
                            </div>

                            {/* Salesperson Info */}
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-200 dark:border-blue-800">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-blue-600 dark:text-blue-400 mb-2">Salesperson (Recorded By)</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <span className="text-muted-foreground">Name: </span>
                                        <span className="font-medium">{selectedInvoice.user?.name || selectedInvoice.user?.username || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Username: </span>
                                        <span className="font-medium">@{selectedInvoice.user?.username || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Phone: </span>
                                        <span className="font-medium">{selectedInvoice.user?.phone || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Address: </span>
                                        <span className="font-medium">{selectedInvoice.user?.address || 'N/A'}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Buyer Info */}
                            <div className="p-4 bg-amber-50 dark:bg-amber-900/20 rounded-xl border border-amber-200 dark:border-amber-800">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-amber-600 dark:text-amber-400 mb-2">Buyer Information</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <span className="text-muted-foreground">Name: </span>
                                        <span className="font-medium">{selectedInvoice.customerName || 'Walk-in Customer'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Phone: </span>
                                        <span className="font-medium">{selectedInvoice.customerPhone || 'N/A'}</span>
                                    </div>
                                    <div className="col-span-2">
                                        <span className="text-muted-foreground">Address: </span>
                                        <span className="font-medium">{selectedInvoice.customerAddress || 'N/A'}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Items Table */}
                            <div className="space-y-3">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-muted-foreground px-1">Order Items</h4>
                                <div className="border border-border rounded-xl overflow-hidden">
                                    <table className="w-full text-sm">
                                        <thead className="bg-secondary/20 text-muted-foreground font-medium">
                                            <tr>
                                                <th className="px-4 py-2 text-left">Item</th>
                                                <th className="px-4 py-2 text-center">Qty</th>
                                                <th className="px-4 py-2 text-right">Price</th>
                                                <th className="px-4 py-2 text-right">Subtotal</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-border">
                                            {selectedInvoice.items?.map(item => (
                                                <tr key={item.id} className="hover:bg-muted/30">
                                                    <td className="px-4 py-3">
                                                        <div className="font-medium">{item.product.name}</div>
                                                        <div className="text-[10px] text-muted-foreground">{item.product.sku}</div>
                                                    </td>
                                                    <td className="px-4 py-3 text-center">{item.quantity}</td>
                                                    <td className="px-4 py-3 text-right">EGP {item.unitPrice.toLocaleString()}</td>
                                                    <td className="px-4 py-3 text-right font-bold">EGP {item.subtotal.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        <tfoot className="bg-secondary/10 font-bold border-t border-border">
                                            <tr>
                                                <td colSpan={3} className="px-4 py-3 text-right">GRAND TOTAL</td>
                                                <td className="px-4 py-3 text-right text-primary text-lg">EGP {Number(selectedInvoice.totalAmount).toLocaleString()}</td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>

                                {/* Premium Arabic Financial Footer */}
                                <div className="mt-6 border-2 border-primary/20 rounded-2xl overflow-hidden bg-primary/5 shadow-inner">
                                    <div className="grid grid-cols-2 md:grid-cols-4 divide-x-2 divide-primary/20 rtl text-right font-bold" dir="rtl">
                                        <div className="p-4 flex flex-col items-center justify-center gap-1">
                                            <span className="text-[10px] text-muted-foreground">الرصيد السابق</span>
                                            <span className="text-lg">EGP {Number(selectedInvoice.previousBalance || 0).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1 bg-primary/10">
                                            <span className="text-[10px] text-primary">الصافي</span>
                                            <span className="text-xl text-primary">EGP {Number(selectedInvoice.totalAmount).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1">
                                            <span className="text-[10px] text-green-600">مستلم</span>
                                            <span className="text-lg text-green-600">EGP {Number(selectedInvoice.amountPaid || 0).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1 bg-primary/5">
                                            <span className="text-[10px] text-red-600 font-black">الرصيد الحالي</span>
                                            <span className="text-xl text-red-600 underline decoration-double">EGP {Number(selectedInvoice.currentBalance || 0).toLocaleString()}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 border-t border-border bg-secondary/5 flex gap-3">
                            <button
                                onClick={() => handleDownload(selectedInvoice)}
                                className="flex-1 flex items-center justify-center gap-2 py-3 bg-secondary hover:bg-secondary/80 rounded-xl font-bold transition-all"
                            >
                                <span className="flex items-center gap-2">
                                    <Printer size={18} />
                                    Quick Print
                                </span>
                            </button>
                            <button
                                onClick={() => window.open(`/invoices/${selectedInvoice.id}/print`, '_blank')}
                                className="flex-1 flex items-center justify-center gap-2 py-3 bg-blue-600 text-white rounded-xl font-bold transition-all hover:bg-blue-700"
                            >
                                <FileText size={18} />
                                Official Invoice (فاتورة)
                            </button>
                            <button
                                onClick={() => setSelectedInvoice(null)}
                                className="flex-1 py-3 bg-primary text-primary-foreground rounded-xl font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20"
                            >
                                Close
                            </button>
                        </div>

                        <div className="px-6 pb-6 pt-2 border-t border-border/50 bg-red-50/20 dark:bg-red-950/5 flex flex-col gap-2">
                            <h4 className="text-[10px] font-bold uppercase text-red-500 tracking-widest pl-1">Actions</h4>
                            <button
                                onClick={() => setShowRefundModal(true)}
                                className="flex items-center justify-center gap-2 py-3 bg-red-100 dark:bg-red-900/20 text-red-600 rounded-xl font-bold transition-all hover:bg-red-200 dark:hover:bg-red-900/40"
                            >
                                <RefreshCcw size={18} />
                                Process Item Refund
                            </button>
                        </div>
                    </div>
                </div>
            )
            }

            {/* Refund Modal */}
            {showRefundModal && selectedInvoice && (
                <RefundModal
                    invoice={selectedInvoice}
                    onClose={() => setShowRefundModal(false)}
                    onSuccess={() => {
                        setShowRefundModal(false);
                        setSelectedInvoice(null);
                        getInvoices().then(data => setInvoices(data as any));
                    }}
                />
            )}


            {/* Hidden Print Content */}
            <div id="print-invoice-list" className="hidden">
                <style>{`
                    @media print {
                        table { width: 100%; border-collapse: collapse; font-size: 12px; }
                        th, td { border-bottom: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f5f5f5; font-weight: bold; }
                        .text-right { text-align: right; }
                        .font-bold { font-weight: bold; }
                    }
                `}</style>
                <div className="mb-4">
                    <h1 className="text-xl font-bold">Invoices Report</h1>
                    <p className="text-sm text-gray-500">Generated on {new Date().toLocaleString()}</p>
                </div>
                <table>
                    <thead>
                        <tr>
                            <th>Date</th>
                            <th>Invoice #</th>
                            <th>Customer</th>
                            <th className="text-right">Amount</th>
                            <th>Payment</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredInvoices.map(inv => (
                            <tr key={inv.id}>
                                <td>{new Date(inv.date).toLocaleDateString()}</td>
                                <td>{inv.id.slice(0, 8).toUpperCase()}</td>
                                <td>{inv.customerName || (inv.user ? inv.user.username : 'Walk-in')}</td>
                                <td className="text-right">EGP {Number(inv.totalAmount).toLocaleString()}</td>
                                <td>{inv.paymentMethod}</td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot>
                        <tr>
                            <td colSpan={3} className="text-right font-bold pt-4">TOTAL</td>
                            <td className="text-right font-bold pt-4">
                                EGP {filteredInvoices.reduce((sum, inv) => sum + Number(inv.totalAmount), 0).toLocaleString()}
                            </td>
                            <td></td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div >
    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
    LayoutDashboard,
    Package,
    ShoppingCart,
    Users,
    FileText,
    LogOut,
    Menu,
    X,
    ArrowLeftRight,
    ClipboardCheck,
    TrendingUp,
    UserCheck,
    BarChart3,
    ScrollText,
    DollarSign,
    RefreshCcw
} from 'lucide-react';
import clsx from 'clsx';
import { signOut } from '@/app/actions/auth';
import { getMenuItemsForUser, getCurrentUser } from '@/app/actions/permissions';

const iconMap: Record<string, any> = {
    '/dashboard': LayoutDashboard,
    '/sales': ShoppingCart,
    '/stocktake': ClipboardCheck,
    '/movements': ArrowLeftRight,
    '/products': Package,
    '/invoices': FileText,
    '/customers': Users,
    '/analytics': BarChart3,
    '/profits': TrendingUp,
    '/staff-sales': UserCheck,
    '/logs': ScrollText,
    '/users': Users,
    '/expenses': DollarSign,
    '/refunds': RefreshCcw,
};

interface MenuItem {
    to: string;
    label: string;
    labelAr: string;
    permission: string;
}

interface CurrentUser {
    id: string;
    username: string;
    name: string | null;
    role: string;
}

const SidebarItem = ({ to, icon: Icon, label, labelAr, active }: { to: string, icon: any, label: string, labelAr: string, active: boolean }) => (
    <Link prefetch={false}
        href={to}
        className={clsx(
            "flex items-center gap-3 px-4 py-3 rounded-lg transition-colors mx-2",
            active ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-secondary hover:text-foreground"
        )}
    >
        <Icon size={20} />
        <div className="flex flex-col">
            <span className="font-bold text-sm">{labelAr}</span>
            <span className="text-[10px] opacity-70">{label}</span>
        </div>
    </Link>
);

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
    const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
    const pathname = usePathname();

    useEffect(() => {
        // Load menu items based on user permissions
        getMenuItemsForUser().then(setMenuItems);
        getCurrentUser().then(setCurrentUser);
    }, []);

    return (
        <div className="flex h-screen bg-background text-foreground overflow-hidden">
            {/* Mobile Sidebar Overlay */}
            {isSidebarOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-20 md:hidden"
                    onClick={() => setSidebarOpen(false)}
                />
            )}

            {/* Sidebar */}
            <aside className={clsx(
                "fixed md:relative z-30 w-64 h-full bg-card border-r border-border flex flex-col transition-transform duration-300",
                !isSidebarOpen ? "-translate-x-full md:translate-x-0" : "translate-x-0"
            )}>
                <div className="p-6 border-b border-border flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden flex-shrink-0">
                        <img src="/logo.webp" alt="Logo" className="w-full h-full object-cover" />
                    </div>
                    <h1 className="text-xl font-black bg-gradient-to-r from-primary to-orange-600 bg-clip-text text-transparent uppercase tracking-tighter">
                        EPIC COMPANY
                    </h1>
                    <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="md:hidden ml-auto">
                        <X />
                    </button>
                </div>

                <nav className="flex-1 py-6 space-y-1 overflow-y-auto">
                    {menuItems.map((item) => (
                        <SidebarItem
                            key={item.to}
                            to={item.to}
                            icon={iconMap[item.to] || LayoutDashboard}
                            label={item.label}
                            labelAr={item.labelAr}
                            active={pathname === item.to || pathname.startsWith(item.to + '/')}
                        />
                    ))}
                </nav>

                <div className="p-4 border-t border-border">
                    <button
                        onClick={async () => {
                            await signOut();
                        }}
                        className="flex items-center gap-3 px-4 py-3 w-full text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                    >
                        <LogOut size={20} />
                        <span className="font-medium">Logout</span>
                    </button>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 flex flex-col h-full overflow-hidden relative">
                <header className="h-16 border-b border-border bg-card/50 backdrop-blur px-6 flex items-center justify-between">
                    <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-secondary rounded-lg md:hidden">
                        <Menu />
                    </button>
                    <div className="flex items-center gap-4">
                        <div className="text-right">
                            <div className="text-sm font-medium">{currentUser?.name || currentUser?.username || 'User'}</div>
                            <div className="text-[10px] text-muted-foreground uppercase">{currentUser?.role || 'Loading...'}</div>
                        </div>
                        <div className={clsx(
                            "w-8 h-8 rounded-full flex items-center justify-center font-bold text-white",
                            currentUser?.role === 'ROOT' ? 'bg-purple-500' :
                                currentUser?.role === 'ADMIN' ? 'bg-blue-500' :
                                    currentUser?.role === 'ACCOUNTANT' ? 'bg-green-500' :
                                        currentUser?.role === 'SALESPERSON' ? 'bg-orange-500' :
                                            'bg-gray-500'
                        )}>
                            {(currentUser?.name || currentUser?.username || 'U')[0].toUpperCase()}
                        </div>
                    </div>
                </header>

                <div className="flex-1 overflow-auto p-6 bg-secondary/20">
                    {children}
                </div>
            </main>
        </div>
    );
}

'use client';

import { Suspense, useState, useEffect } from 'react';
import { useSearchParams } from 'next/navigation';
import { getAuditLogs } from '@/app/actions/audit';
import { getUsers } from '@/app/actions/users';
import { ScrollText, RefreshCcw, Loader2, User, ChevronLeft, ChevronRight, Filter } from 'lucide-react';
import clsx from 'clsx';

const ITEMS_PER_PAGE = 50;

function LogsContent() {
    const searchParams = useSearchParams();
    const [logs, setLogs] = useState<any[]>([]);
    const [users, setUsers] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [selectedUserId, setSelectedUserId] = useState<string>(searchParams.get('user') || '');
    const [pagination, setPagination] = useState({ total: 0, pages: 1, current: 1 });

    const fetchLogs = async () => {
        setLoading(true);
        try {
            const res = await getAuditLogs(page, ITEMS_PER_PAGE, selectedUserId || undefined);
            if (res.success && res.logs) {
                setLogs(res.logs);
                setPagination(res.pagination || { total: 0, pages: 1, current: 1 });
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        getUsers().then(setUsers);
    }, []);

    useEffect(() => {
        fetchLogs();
    }, [page, selectedUserId]);

    const getActionColor = (action: string) => {
        if (action.includes('SALE')) return 'bg-green-100 text-green-700 border-green-200';
        if (action.includes('DELETE')) return 'bg-red-100 text-red-700 border-red-200';
        if (action.includes('UPDATE')) return 'bg-blue-100 text-blue-700 border-blue-200';
        if (action.includes('CREATE')) return 'bg-purple-100 text-purple-700 border-purple-200';
        return 'bg-secondary text-secondary-foreground border-border';
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <ScrollText className="text-primary" />
                        سجل النظام
                    </h2>
                    <p className="text-muted-foreground">Audit Logs & Activity History</p>
                </div>
                <button
                    onClick={fetchLogs}
                    disabled={loading}
                    className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50"
                >
                    <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                    Refresh
                </button>
            </div>

            {/* User Filter */}
            <div className="flex items-center gap-3 bg-card p-3 rounded-lg border border-border">
                <Filter size={16} className="text-muted-foreground" />
                <span className="text-sm font-medium">Filter by User:</span>
                <select
                    value={selectedUserId}
                    onChange={(e) => { setSelectedUserId(e.target.value); setPage(1); }}
                    className="bg-secondary/50 border border-border rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 ring-primary/20"
                >
                    <option value="">All Users</option>
                    {users.map((u) => (
                        <option key={u.id} value={u.id}>
                            {u.name || u.username} ({u.role})
                        </option>
                    ))}
                </select>
                {selectedUserId && (
                    <button
                        onClick={() => { setSelectedUserId(''); setPage(1); }}
                        className="text-xs text-primary hover:underline"
                    >
                        Clear filter
                    </button>
                )}
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Status & Action</th>
                            <th className="px-6 py-4">Details</th>
                            <th className="px-6 py-4">User</th>
                            <th className="px-6 py-4 text-right">Time</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={4} className="px-6 py-12 text-center text-muted-foreground"><Loader2 className="animate-spin mx-auto" /></td></tr>
                        ) : logs.length === 0 ? (
                            <tr><td colSpan={4} className="px-6 py-12 text-center text-muted-foreground">No logs found.</td></tr>
                        ) : (
                            logs.map((log) => (
                                <tr key={log.id} className="hover:bg-muted/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <span className={clsx("px-2.5 py-1 rounded-full text-xs font-bold border", getActionColor(log.action))}>
                                            {log.action}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 font-medium text-foreground/80">{log.details}</td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2 text-muted-foreground">
                                            <User size={14} />
                                            {log.user?.name || log.user?.username || 'System'}
                                            {log.user?.role && <span className="text-[10px] bg-secondary px-1 rounded">{log.user.role}</span>}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right tabular-nums text-muted-foreground">
                                        {new Date(log.timestamp).toLocaleString()}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>

                {/* Pagination */}
                {pagination.pages > 1 && (
                    <div className="px-6 py-4 border-t border-border flex items-center justify-between bg-secondary/10">
                        <div className="text-sm text-muted-foreground">
                            Page {page} of {pagination.pages} ({pagination.total} entries)
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={() => setPage(p => Math.max(1, p - 1))}
                                disabled={page === 1}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <button
                                onClick={() => setPage(p => Math.min(pagination.pages, p + 1))}
                                disabled={page === pagination.pages}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

export default function LogsPage() {
    return (
        <Suspense fallback={<div className="flex justify-center py-12"><Loader2 className="animate-spin" /></div>}>
            <LogsContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { getStockMovements } from '@/app/actions/transactions';
import {
    History, RefreshCcw, Loader2,
    ArrowDownLeft, ArrowUpRight, ShoppingCart, ArrowRightLeft,
    MapPin, Package, Calendar
} from 'lucide-react';
import clsx from 'clsx';

const ITEMS_PER_PAGE = 50;

type TransactionType = 'SALE' | 'IN' | 'OUT' | 'TRANSFER' | 'RETURN';

export default function MovementsPage() {
    const [transactions, setTransactions] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [filterType, setFilterType] = useState('ALL');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [pagination, setPagination] = useState({ total: 0, pages: 1, current: 1 });

    const fetchData = async () => {
        setLoading(true);
        try {
            const res = await getStockMovements(page, ITEMS_PER_PAGE, { type: filterType, startDate: startDate || undefined, endDate: endDate || undefined });
            if (res.success && res.movements) {
                setTransactions(res.movements);
                setPagination(res.pagination || { total: 0, pages: 1, current: 1 });
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [page, filterType, startDate, endDate]);

    const getTypeConfig = (type: TransactionType) => {
        switch (type) {
            case 'SALE': return { icon: ShoppingCart, color: 'text-blue-600 bg-blue-100 border-blue-200', label: 'Sale' };
            case 'IN': return { icon: ArrowDownLeft, color: 'text-green-600 bg-green-100 border-green-200', label: 'Stock In' };
            case 'OUT': return { icon: ArrowUpRight, color: 'text-red-600 bg-red-100 border-red-200', label: 'Stock Out' };
            case 'TRANSFER': return { icon: ArrowRightLeft, color: 'text-orange-600 bg-orange-100 border-orange-200', label: 'Transfer' };
            case 'RETURN': return { icon: RefreshCcw, color: 'text-purple-600 bg-purple-100 border-purple-200', label: 'Return' };
            default: return { icon: History, color: 'text-gray-600 bg-gray-100 border-gray-200', label: type };
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <History className="text-primary" />
                        حركات المخزون
                    </h2>
                    <p className="text-muted-foreground">Stock Movement History</p>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    <select
                        value={filterType}
                        onChange={(e) => setFilterType(e.target.value)}
                        className="px-3 py-2 bg-background border border-input rounded-lg text-sm font-medium focus:ring-2 focus:ring-primary"
                    >
                        <option value="ALL">All Types</option>
                        <option value="SALE">Sales</option>
                        <option value="IN">Stock In</option>
                        <option value="OUT">Stock Out</option>
                        <option value="TRANSFER">Transfers</option>
                    </select>

                    <div className="flex items-center gap-2 bg-card border border-border p-1 rounded-lg">
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-transparent text-sm p-2 outline-none"
                            placeholder="From"
                        />
                        <span className="text-muted-foreground">-</span>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-transparent text-sm p-2 outline-none"
                            placeholder="To"
                        />
                    </div>

                    <button onClick={fetchData} disabled={loading} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50">
                        <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                        Refresh
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center py-20"><Loader2 className="animate-spin text-muted-foreground" size={32} /></div>
                ) : transactions.length === 0 ? (
                    <div className="text-center py-20 bg-card border border-border rounded-xl text-muted-foreground">
                        No transactions found matching your filters.
                    </div>
                ) : (
                    transactions.map((tx) => {
                        const { icon: Icon, color, label } = getTypeConfig(tx.type);
                        return (
                            <div key={tx.id} className="bg-card border border-border rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow">
                                <div className="flex flex-col md:flex-row gap-4 justify-between">
                                    {/* Header: Type & Date */}
                                    <div className="flex items-start gap-4 min-w-[200px]">
                                        <div className={clsx("p-3 rounded-xl border", color)}>
                                            <Icon size={20} />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-foreground">{label}</h4>
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground mt-1">
                                                <Calendar size={12} />
                                                {new Date(tx.date).toLocaleString()}
                                            </div>
                                            {tx.createdById && <div className="text-xs text-muted-foreground mt-0.5">By: {tx.createdById}</div>}
                                        </div>
                                    </div>

                                    {/* Items List */}
                                    <div className="flex-1 space-y-2">
                                        {tx.items.map((item: any) => (
                                            <div key={item.id} className="flex items-center justify-between text-sm p-2 bg-secondary/20 rounded-lg">
                                                <div className="flex items-center gap-2 font-medium">
                                                    <Package size={14} className="text-muted-foreground" />
                                                    {item.product.name}
                                                    <span className="text-xs text-muted-foreground font-mono">({item.product.sku})</span>
                                                </div>
                                                <div className="font-bold font-mono">
                                                    x{item.quantity}
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {/* Locations */}
                                    <div className="min-w-[150px] text-right space-y-2 text-sm">
                                        {(tx.fromLocation || tx.type === 'SALE' || tx.type === 'OUT') && (
                                            <div className="flex items-center justify-end gap-1.5 text-muted-foreground">
                                                <span className="text-xs uppercase font-bold">From</span>
                                                <span className="font-medium text-foreground">{tx.fromLocation?.name || 'Unknown'}</span>
                                                <MapPin size={14} />
                                            </div>
                                        )}
                                        {tx.toLocation && (
                                            <div className="flex items-center justify-end gap-1.5 text-muted-foreground">
                                                <span className="text-xs uppercase font-bold">To</span>
                                                <span className="font-medium text-foreground">{tx.toLocation?.name}</span>
                                                <MapPin size={14} className="text-green-500" />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}

                {/* Pagination Controls */}
                {pagination.pages > 1 && (
                    <div className="flex justify-center gap-2 pt-4">
                        <button
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1}
                            className="px-4 py-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                        >
                            Previous
                        </button>
                        <span className="px-4 py-2 text-sm text-muted-foreground self-center">
                            Page {page} of {pagination.pages}
                        </span>
                        <button
                            onClick={() => setPage(p => Math.min(pagination.pages, p + 1))}
                            disabled={page === pagination.pages}
                            className="px-4 py-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                        >
                            Next
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Tag, Search, Plus, Edit, Trash2, DollarSign, Percent } from 'lucide-react';
import { getInventory, getCategories } from '@/app/actions/inventory';

export default function PricingPage() {
    const [products, setProducts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getInventory().then(data => {
            setProducts(data);
            setLoading(false);
        });
    }, []);

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <Tag className="text-primary" />
                        التسعير
                    </h2>
                    <p className="text-muted-foreground">Price Management & Margins</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-all">
                    <Percent size={16} />
                    Bulk Update
                </button>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Product</th>
                            <th className="px-6 py-4 text-right">Cost (EGP)</th>
                            <th className="px-6 py-4 text-right">Selling (EGP)</th>
                            <th className="px-6 py-4 text-right">Margin</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">
                                    Loading pricing data...
                                </td>
                            </tr>
                        ) : products.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">
                                    No products found.
                                </td>
                            </tr>
                        ) : (
                            products.map((item) => {
                                const cost = Number(item.product.costPrice);
                                const sell = Number(item.product.baseSellingPrice);
                                const margin = sell > 0 ? ((sell - cost) / sell * 100).toFixed(1) : 0;
                                return (
                                    <tr key={item.id} className="hover:bg-muted/50">
                                        <td className="px-6 py-4 font-medium">{item.product.name}</td>
                                        <td className="px-6 py-4 text-right font-mono">{cost.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-right font-mono font-bold">{sell.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-right">
                                            <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs font-bold">
                                                {margin}%
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button className="p-2 hover:bg-secondary rounded-lg">
                                                <Edit size={14} />
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { Package, Search, Plus, RefreshCcw, Loader2, X, Check, Edit, Trash2, AlertCircle, Tag, Boxes, FolderPlus, Settings, ArrowUpDown, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronDown, MapPin, Percent } from 'lucide-react';
import { getUnifiedProducts, getCategories, createProduct, updateProduct, createCategory, deleteCategory } from '@/app/actions/inventory';
import clsx from 'clsx';

type SortField = 'name' | 'sku' | 'category' | 'stock' | 'cost' | 'sell' | 'margin' | 'percent';
type SortOrder = 'asc' | 'desc';

const ITEMS_PER_PAGE = 15;

export default function ProductsPage() {
    const [products, setProducts] = useState<any[]>([]);
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isEditMode, setIsEditMode] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [expandedRow, setExpandedRow] = useState<string | null>(null);

    // Sorting state
    const [sortField, setSortField] = useState<SortField>('name');
    const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

    // Pagination state
    const [currentPage, setCurrentPage] = useState(1);

    // Category modal state
    const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');
    const [categoryError, setCategoryError] = useState<string | null>(null);
    const [categorySubmitting, setCategorySubmitting] = useState(false);

    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        categoryId: '',
        costPrice: 0,
        baseSellingPrice: 0,
        unit: 'piece',
        initialQuantity: 0
    });

    const fetchData = async () => {
        setLoading(true);
        try {
            const [prods, cats] = await Promise.all([getUnifiedProducts(), getCategories()]);
            setProducts(prods);
            setCategories(cats);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchData(); }, []);

    // Reset to page 1 when filters change
    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, categoryFilter, sortField, sortOrder]);

    const openAddModal = () => {
        setIsEditMode(false);
        setEditingId(null);
        setFormData({ name: '', sku: '', categoryId: '', costPrice: 0, baseSellingPrice: 0, unit: 'piece', initialQuantity: 0 });
        setError(null);
        setIsModalOpen(true);
    };

    const openEditModal = (product: any) => {
        setIsEditMode(true);
        setEditingId(product.id);
        setFormData({
            name: product.name,
            sku: product.sku,
            categoryId: product.categoryId,
            costPrice: product.costPrice,
            baseSellingPrice: product.baseSellingPrice,
            unit: product.unit,
            initialQuantity: product.totalStock
        });
        setError(null);
        setIsModalOpen(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.name || !formData.sku || !formData.categoryId) return;
        setSubmitting(true);
        setError(null);
        try {
            let result;
            if (isEditMode && editingId) {
                const { initialQuantity, ...updateData } = formData;
                result = await updateProduct(editingId, updateData);
            } else {
                result = await createProduct(formData);
            }
            if (!result.success) {
                setError(result.error || 'Operation failed');
                return;
            }
            await fetchData();
            setIsModalOpen(false);
        } catch (err: any) {
            setError("Connection error. Please try again.");
        } finally {
            setSubmitting(false);
        }
    };

    const handleAddCategory = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCategoryName.trim()) return;
        setCategorySubmitting(true);
        setCategoryError(null);
        try {
            const result = await createCategory(newCategoryName.trim());
            if (!result.success) {
                setCategoryError(result.error || 'Failed to create category');
                return;
            }
            setNewCategoryName('');
            await fetchData();
        } catch {
            setCategoryError('Connection error.');
        } finally {
            setCategorySubmitting(false);
        }
    };

    const handleDeleteCategory = async (id: string) => {
        setCategorySubmitting(true);
        setCategoryError(null);
        try {
            const result = await deleteCategory(id);
            if (!result.success) {
                setCategoryError(result.error || 'Failed to delete');
                return;
            }
            await fetchData();
        } catch {
            setCategoryError('Connection error.');
        } finally {
            setCategorySubmitting(false);
        }
    };

    const handleSort = (field: SortField) => {
        if (sortField === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortField(field);
            setSortOrder('asc');
        }
    };

    const getSortIcon = (field: SortField) => {
        if (sortField !== field) return <ArrowUpDown size={14} className="opacity-30" />;
        return sortOrder === 'asc' ? <ArrowUp size={14} className="text-primary" /> : <ArrowDown size={14} className="text-primary" />;
    };

    // Filter and sort products
    const filteredAndSortedItems = useMemo(() => {
        const result = (products || []).filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                p.sku.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = categoryFilter === 'all' || p.categoryId === categoryFilter;
            return matchesSearch && matchesCategory;
        });

        result.sort((a, b) => {
            let aVal: any, bVal: any;
            switch (sortField) {
                case 'name': aVal = a.name.toLowerCase(); bVal = b.name.toLowerCase(); break;
                case 'sku': aVal = a.sku.toLowerCase(); bVal = b.sku.toLowerCase(); break;
                case 'category': aVal = a.categoryName.toLowerCase(); bVal = b.categoryName.toLowerCase(); break;
                case 'stock': aVal = a.totalStock; bVal = b.totalStock; break;
                case 'cost': aVal = a.costPrice; bVal = b.costPrice; break;
                case 'sell': aVal = a.baseSellingPrice; bVal = b.baseSellingPrice; break;
                case 'percent': aVal = a.percentOfTotal; bVal = b.percentOfTotal; break;
                case 'margin':
                    aVal = a.baseSellingPrice > 0 ? ((a.baseSellingPrice - a.costPrice) / a.baseSellingPrice) : 0;
                    bVal = b.baseSellingPrice > 0 ? ((b.baseSellingPrice - b.costPrice) / b.baseSellingPrice) : 0;
                    break;
                default: return 0;
            }
            if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
            return 0;
        });

        return result;
    }, [products, searchQuery, categoryFilter, sortField, sortOrder]);

    // Pagination
    const totalPages = Math.ceil(filteredAndSortedItems.length / ITEMS_PER_PAGE);
    const paginatedItems = filteredAndSortedItems.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    const SortableHeader = ({ field, children, className = "" }: { field: SortField, children: React.ReactNode, className?: string }) => (
        <th
            className={clsx("px-4 py-3 cursor-pointer hover:bg-secondary/50 transition-colors select-none text-xs", className)}
            onClick={() => handleSort(field)}
        >
            <div className="flex items-center gap-1">
                {children}
                {getSortIcon(field)}
            </div>
        </th>
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <Package className="text-primary" />
                        الأصناف والتسعير
                    </h2>
                    <p className="text-muted-foreground">Products, Pricing & Stock</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={fetchData} disabled={loading} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50">
                        <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                    </button>
                    <button onClick={() => setIsCategoryModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors">
                        <Settings size={16} />
                        Categories
                    </button>
                    <button onClick={openAddModal} className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg transition-all shadow-sm active:scale-95">
                        <Plus size={16} />
                        New Product
                    </button>
                </div>
            </div>

            {/* Filters Bar */}
            <div className="flex flex-wrap items-center gap-4 bg-card p-4 rounded-xl border border-border shadow-sm">
                {/* Category Filter */}
                <select
                    value={categoryFilter}
                    onChange={(e) => setCategoryFilter(e.target.value)}
                    className="px-3 py-2 bg-background border border-input rounded-lg text-sm"
                >
                    <option value="all">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>

                {/* Search */}
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={18} />
                    <input
                        type="text"
                        placeholder="Search products..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-background border border-input rounded-lg focus:outline-none focus:ring-2 focus:ring-ring"
                    />
                </div>

                {/* Results count */}
                <div className="text-sm text-muted-foreground">
                    {filteredAndSortedItems.length} products
                </div>
            </div>

            {/* Unified Table */}
            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-4 py-3 w-8"></th>
                            <SortableHeader field="name">Product</SortableHeader>
                            <SortableHeader field="sku">SKU</SortableHeader>
                            <SortableHeader field="category">Category</SortableHeader>
                            <th className="px-4 py-3 text-xs">Unit</th>
                            <SortableHeader field="cost" className="text-right">Cost</SortableHeader>
                            <SortableHeader field="sell" className="text-right">Sell</SortableHeader>
                            <SortableHeader field="margin" className="text-right">Margin</SortableHeader>
                            <SortableHeader field="stock" className="text-right">Stock</SortableHeader>
                            <SortableHeader field="percent" className="text-right">% Total</SortableHeader>
                            <th className="px-4 py-3 text-right text-xs">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={11} className="px-6 py-12 text-center text-muted-foreground"><Loader2 className="animate-spin mx-auto" /></td></tr>
                        ) : paginatedItems.length === 0 ? (
                            <tr><td colSpan={11} className="px-6 py-12 text-center text-muted-foreground">No products found.</td></tr>
                        ) : (
                            paginatedItems.map((p) => {
                                const margin = p.baseSellingPrice > 0 ? ((p.baseSellingPrice - p.costPrice) / p.baseSellingPrice * 100).toFixed(1) : '0';
                                const isExpanded = expandedRow === p.id;
                                return (
                                    <>
                                        <tr key={p.id} className="hover:bg-muted/50 transition-colors group">
                                            <td className="px-4 py-3">
                                                {p.locationBreakdown.length > 0 && (
                                                    <button
                                                        onClick={() => setExpandedRow(isExpanded ? null : p.id)}
                                                        className="p-1 rounded hover:bg-secondary transition-colors"
                                                    >
                                                        <ChevronDown size={14} className={clsx("transition-transform", isExpanded && "rotate-180")} />
                                                    </button>
                                                )}
                                            </td>
                                            <td className="px-4 py-3 font-semibold">{p.name}</td>
                                            <td className="px-4 py-3 font-mono text-xs">{p.sku}</td>
                                            <td className="px-4 py-3"><span className="px-2 py-1 bg-secondary rounded text-[10px] font-bold">{p.categoryName}</span></td>
                                            <td className="px-4 py-3 text-xs capitalize text-muted-foreground">{p.unit}</td>
                                            <td className="px-4 py-3 text-right font-mono text-xs">{p.costPrice.toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right font-mono text-xs font-bold">{p.baseSellingPrice.toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right">
                                                <span className={clsx(
                                                    "px-2 py-0.5 rounded text-[10px] font-bold",
                                                    Number(margin) >= 20 ? "bg-green-100 text-green-700" : Number(margin) >= 10 ? "bg-yellow-100 text-yellow-700" : "bg-red-100 text-red-700"
                                                )}>
                                                    {margin}%
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <span className={clsx("font-bold", p.totalStock < 10 ? "text-red-500" : "")}>{p.totalStock}</span>
                                                {p.totalStock < 10 && <AlertCircle size={12} className="inline ml-1 text-red-500" />}
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="flex items-center justify-end gap-2">
                                                    <div className="w-16 h-1.5 bg-secondary rounded-full overflow-hidden">
                                                        <div
                                                            className="h-full bg-primary rounded-full transition-all"
                                                            style={{ width: `${Math.min(p.percentOfTotal, 100)}%` }}
                                                        />
                                                    </div>
                                                    <span className="text-xs font-mono w-12 text-right">{p.percentOfTotal}%</span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <button onClick={() => openEditModal(p)} className="p-2 hover:bg-secondary rounded-lg"><Edit size={14} /></button>
                                            </td>
                                        </tr>
                                        {/* Expanded Location Breakdown */}
                                        {isExpanded && (
                                            <tr key={`${p.id}-expanded`} className="bg-secondary/10">
                                                <td colSpan={11} className="px-4 py-3">
                                                    <div className="ml-8 space-y-1">
                                                        <div className="text-[10px] font-bold uppercase text-muted-foreground mb-2">Stock by Location</div>
                                                        {p.locationBreakdown.map((loc: any) => (
                                                            <div key={loc.locationId} className="flex items-center gap-3 text-sm py-1.5 px-3 rounded-lg hover:bg-secondary/30">
                                                                <MapPin size={14} className={loc.locationType === 'WAREHOUSE' ? 'text-blue-500' : 'text-orange-500'} />
                                                                <span className="font-medium flex-1">{loc.locationName}</span>
                                                                <span className={clsx(
                                                                    "px-2 py-0.5 rounded text-[10px] font-bold",
                                                                    loc.locationType === 'WAREHOUSE' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'
                                                                )}>
                                                                    {loc.locationType}
                                                                </span>
                                                                <span className="font-bold font-mono w-16 text-right">{loc.quantity}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </td>
                                            </tr>
                                        )}
                                    </>
                                );
                            })
                        )}
                    </tbody>
                </table>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="px-6 py-4 border-t border-border flex items-center justify-between bg-secondary/10">
                        <div className="text-sm text-muted-foreground">
                            Showing {((currentPage - 1) * ITEMS_PER_PAGE) + 1} - {Math.min(currentPage * ITEMS_PER_PAGE, filteredAndSortedItems.length)} of {filteredAndSortedItems.length}
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                disabled={currentPage === 1}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30 disabled:cursor-not-allowed"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <div className="flex gap-1">
                                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                    let page;
                                    if (totalPages <= 5) {
                                        page = i + 1;
                                    } else if (currentPage <= 3) {
                                        page = i + 1;
                                    } else if (currentPage >= totalPages - 2) {
                                        page = totalPages - 4 + i;
                                    } else {
                                        page = currentPage - 2 + i;
                                    }
                                    return (
                                        <button
                                            key={page}
                                            onClick={() => setCurrentPage(page)}
                                            className={clsx(
                                                "w-8 h-8 rounded-lg text-sm font-medium",
                                                currentPage === page ? "bg-primary text-primary-foreground" : "hover:bg-secondary"
                                            )}
                                        >
                                            {page}
                                        </button>
                                    );
                                })}
                            </div>
                            <button
                                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                disabled={currentPage === totalPages}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30 disabled:cursor-not-allowed"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Product Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-lg rounded-2xl border border-border shadow-2xl overflow-hidden">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <h3 className="text-xl font-bold">{isEditMode ? 'Edit Product' : 'Add New Product'}</h3>
                            <button onClick={() => setIsModalOpen(false)} className="p-1 hover:bg-secondary rounded-full"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            {error && <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm flex items-center gap-2"><AlertCircle size={16} />{error}</div>}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5 col-span-2 sm:col-span-1">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Product Name</label>
                                    <input type="text" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
                                </div>
                                <div className="space-y-1.5 col-span-2 sm:col-span-1">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">SKU</label>
                                    <input type="text" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.sku} onChange={(e) => setFormData({ ...formData, sku: e.target.value })} />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Category</label>
                                    <select className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.categoryId} onChange={(e) => setFormData({ ...formData, categoryId: e.target.value })}>
                                        <option value="">Select Category</option>
                                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Unit</label>
                                    <select className="w-full p-3 rounded-xl border border-border bg-background" value={formData.unit} onChange={(e) => setFormData({ ...formData, unit: e.target.value })}>
                                        <option value="piece">Piece</option>
                                        <option value="kg">Kilogram</option>
                                        <option value="carton">Carton</option>
                                        <option value="liter">Liter</option>
                                    </select>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Cost Price (EGP)</label>
                                    <input type="number" step="0.01" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.costPrice} onChange={(e) => setFormData({ ...formData, costPrice: parseFloat(e.target.value) })} />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Selling Price (EGP)</label>
                                    <input type="number" step="0.01" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.baseSellingPrice} onChange={(e) => setFormData({ ...formData, baseSellingPrice: parseFloat(e.target.value) })} />
                                </div>
                            </div>
                            {!isEditMode && (
                                <div className="space-y-1.5 p-4 bg-primary/5 rounded-xl border border-primary/20">
                                    <label className="text-xs font-bold uppercase text-primary">Opening Stock</label>
                                    <input type="number" className="w-full p-3 rounded-lg border border-border bg-background" required min="0" value={formData.initialQuantity} onChange={(e) => setFormData({ ...formData, initialQuantity: parseInt(e.target.value) || 0 })} />
                                </div>
                            )}
                            <div className="pt-6 flex gap-3">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-3 rounded-xl border border-border hover:bg-secondary font-semibold">Cancel</button>
                                <button type="submit" disabled={submitting} className="flex-1 px-4 py-3 rounded-xl bg-primary text-primary-foreground font-bold hover:bg-primary/90 disabled:opacity-50 flex items-center justify-center gap-2">
                                    {submitting ? <Loader2 className="animate-spin" size={18} /> : (isEditMode ? <Check size={18} /> : <Plus size={18} />)}
                                    {isEditMode ? 'Update' : 'Create'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Category Management Modal */}
            {isCategoryModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-md rounded-2xl border border-border shadow-2xl overflow-hidden">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <FolderPlus size={20} />
                                إدارة الفئات
                                <span className="text-xs font-normal text-muted-foreground">Manage Categories</span>
                            </h3>
                            <button onClick={() => setIsCategoryModalOpen(false)} className="p-1 hover:bg-secondary rounded-full"><X size={20} /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            {categoryError && (
                                <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm">{categoryError}</div>
                            )}

                            {/* Add New Category Form */}
                            <form onSubmit={handleAddCategory} className="flex gap-2">
                                <input
                                    type="text"
                                    placeholder="New category name..."
                                    value={newCategoryName}
                                    onChange={(e) => setNewCategoryName(e.target.value)}
                                    className="flex-1 p-3 rounded-xl border border-border bg-background"
                                />
                                <button
                                    type="submit"
                                    disabled={categorySubmitting || !newCategoryName.trim()}
                                    className="px-4 py-3 bg-primary text-primary-foreground rounded-xl font-bold hover:bg-primary/90 disabled:opacity-50 flex items-center gap-2"
                                >
                                    {categorySubmitting ? <Loader2 className="animate-spin" size={16} /> : <Plus size={16} />}
                                    Add
                                </button>
                            </form>

                            {/* Existing Categories List */}
                            <div className="space-y-2 max-h-[300px] overflow-y-auto">
                                {categories.length === 0 ? (
                                    <div className="text-center py-8 text-muted-foreground">No categories yet.</div>
                                ) : (
                                    categories.map(cat => (
                                        <div key={cat.id} className="flex items-center justify-between p-3 bg-secondary/30 rounded-xl group">
                                            <div>
                                                <span className="font-semibold">{cat.name}</span>
                                                <span className="ml-2 text-xs text-muted-foreground">
                                                    ({cat._count?.products || 0} products)
                                                </span>
                                            </div>
                                            <button
                                                onClick={() => handleDeleteCategory(cat.id)}
                                                disabled={categorySubmitting || (cat._count?.products || 0) > 0}
                                                className="p-2 text-red-500 hover:bg-red-50 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-30 disabled:cursor-not-allowed"
                                                title={(cat._count?.products || 0) > 0 ? "Cannot delete: has products" : "Delete category"}
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, DollarSign, Calendar } from 'lucide-react';
import { getInvoices } from '@/app/actions/invoices';
import { getInventory } from '@/app/actions/inventory';

export default function ProfitsPage() {
    const [invoices, setInvoices] = useState<any[]>([]);
    const [inventory, setInventory] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    // Date Filter
    const [showDateFilter, setShowDateFilter] = useState(false);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        Promise.all([getInvoices(), getInventory()]).then(([inv, stock]) => {
            setInvoices(inv);
            setInventory(stock);
            setLoading(false);
        });
    }, []);

    const filteredInvoices = invoices.filter(inv => {
        const invDate = new Date(inv.date);
        return (!startDate || invDate >= new Date(startDate)) &&
            (!endDate || invDate <= new Date(new Date(endDate).setHours(23, 59, 59)));
    });

    const totalRevenue = filteredInvoices.reduce((sum, inv) => sum + Number(inv.totalAmount), 0);
    const estimatedCost = filteredInvoices.reduce((sum, inv) => {
        const invItems = inv.items || [];
        return sum + invItems.reduce((itemSum: number, item: any) => {
            const prod = inventory.find(i => i.product?.id === item.productId);
            const cost = prod ? Number(prod.product?.costPrice || 0) : 0;
            return itemSum + (cost * item.quantity);
        }, 0);
    }, 0);
    const profit = totalRevenue - estimatedCost;
    const margin = totalRevenue > 0 ? (profit / totalRevenue * 100).toFixed(1) : 0;

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <TrendingUp className="text-primary" />
                        الأرباح
                    </h2>
                    <p className="text-muted-foreground">Profit & Loss Overview</p>
                </div>
                <button
                    onClick={() => setShowDateFilter(!showDateFilter)}
                    className={`flex items-center gap-2 px-4 py-2 border rounded-lg transition-colors ${showDateFilter ? 'bg-secondary border-primary' : 'border-border hover:bg-secondary'}`}
                >
                    <Calendar size={16} />
                    Date Range
                </button>
            </div>

            {/* Date Range Inputs */}
            {showDateFilter && (
                <div className="flex flex-wrap items-center gap-4 p-4 bg-secondary/20 rounded-xl border border-border animate-in slide-in-from-top-2">
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">From:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">To:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <button
                        onClick={() => { setStartDate(''); setEndDate(''); }}
                        className="text-xs text-muted-foreground hover:text-primary transition-colors underline"
                    >
                        Clear Filter
                    </button>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-card border border-border rounded-xl p-6">
                    <div className="flex items-center gap-3 mb-2">
                        <DollarSign className="text-green-500" size={24} />
                        <span className="text-sm text-muted-foreground">Total Revenue</span>
                    </div>
                    <div className="text-3xl font-black text-green-600">
                        EGP {loading ? '...' : totalRevenue.toLocaleString()}
                    </div>
                </div>

                <div className="bg-card border border-border rounded-xl p-6">
                    <div className="flex items-center gap-3 mb-2">
                        <TrendingDown className="text-red-500" size={24} />
                        <span className="text-sm text-muted-foreground">Estimated Cost</span>
                    </div>
                    <div className="text-3xl font-black text-red-600">
                        EGP {loading ? '...' : estimatedCost.toLocaleString()}
                    </div>
                </div>

                <div className="bg-card border border-border rounded-xl p-6">
                    <div className="flex items-center gap-3 mb-2">
                        <TrendingUp className="text-primary" size={24} />
                        <span className="text-sm text-muted-foreground">Net Profit ({margin}%)</span>
                    </div>
                    <div className="text-3xl font-black text-primary">
                        EGP {loading ? '...' : profit.toLocaleString()}
                    </div>
                </div>
            </div>

            <div className="bg-card border border-border rounded-xl p-6">
                <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                    <Calendar size={20} />
                    Recent Sales
                </h3>
                <div className="space-y-3">
                    {loading ? (
                        <p className="text-muted-foreground">Loading...</p>
                    ) : filteredInvoices.slice(0, 5).map(inv => (
                        <div key={inv.id} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                            <div>
                                <div className="font-medium">{inv.customerName || 'Customer'}</div>
                                <div className="text-xs text-muted-foreground">{new Date(inv.date).toLocaleDateString()}</div>
                            </div>
                            <div className="font-bold text-green-600">+EGP {Number(inv.totalAmount).toLocaleString()}</div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { RefreshCcw, Search, Calendar, Loader2, FileText, X, AlertTriangle, User, UserCheck } from 'lucide-react';
import { getRefunds } from '@/app/actions/refunds';
import clsx from 'clsx';

interface RefundItem {
    id: string;
    product: { name: string; sku: string };
    quantity: number;
    unitPrice: number;
    subtotal: number;
    condition: string;
}

interface Refund {
    id: string;
    invoiceId: string;
    totalAmount: number;
    reason: string | null;
    createdAt: Date;
    user: { name: string | null, username: string };
    invoice: { customerName: string | null, customerPhone: string | null };
    items: RefundItem[];
}

export default function RefundHistoryPage() {
    const [refunds, setRefunds] = useState<Refund[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedRefund, setSelectedRefund] = useState<Refund | null>(null);

