'use client';

import { useState, useEffect } from 'react';
import { getUsers, deleteUser, createUser, updateUser } from '@/app/actions/users';
import { getDefaultPermissions, ALL_PERMISSIONS } from '@/lib/permissions';
import { UserPlus, Trash2, Shield, User as UserIcon, Eye, Phone, MapPin, Settings } from 'lucide-react';
import Link from 'next/link';

interface User {
    id: string;
    username: string;
    name: string | null;
    role: string;
    phone: string | null;
    address: string | null;
    permissions: string[];
    createdAt: Date;
}

const ROLE_COLORS: Record<string, string> = {
    ROOT: 'bg-purple-100 text-purple-700 border-purple-200',
    ADMIN: 'bg-blue-100 text-blue-700 border-blue-200',
    ACCOUNTANT: 'bg-green-100 text-green-700 border-green-200',
    SALESPERSON: 'bg-orange-100 text-orange-700 border-orange-200',
    READ_ONLY: 'bg-gray-100 text-gray-700 border-gray-200',
};

export default function UsersPage() {
    const [users, setUsers] = useState<User[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [selectedRole, setSelectedRole] = useState('SALESPERSON');
    const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);
    const [useCustomPermissions, setUseCustomPermissions] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        fetchUsers();
    }, []);

    useEffect(() => {
        // Update default permissions when role changes
        if (!useCustomPermissions) {
            setSelectedPermissions(getDefaultPermissions(selectedRole));
        }
    }, [selectedRole, useCustomPermissions]);

    const fetchUsers = async () => {
        setIsLoading(true);
        const data = await getUsers();
        setUsers(data as User[]);
        setIsLoading(false);
    };

    const handleDelete = async (id: string) => {
        if (confirm('Are you sure you want to delete this user?')) {
            const res = await deleteUser(id);
            if (res.success) {
                fetchUsers();
            } else {
                alert(res.error);
            }
        }
    };

    const openCreateModal = () => {
        setEditingUser(null);
        setSelectedRole('SALESPERSON');
        setSelectedPermissions(getDefaultPermissions('SALESPERSON'));
        setUseCustomPermissions(false);
        setError('');
        setIsModalOpen(true);
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setSelectedRole(user.role);
        setSelectedPermissions(user.permissions.length > 0 ? user.permissions : getDefaultPermissions(user.role));
        setUseCustomPermissions(user.permissions.length > 0);
        setError('');
        setIsModalOpen(true);
    };

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError('');
        const formData = new FormData(e.currentTarget);

        // Add permissions to form data
        formData.set('permissions', JSON.stringify(useCustomPermissions ? selectedPermissions : []));

        if (editingUser) {
            const res = await updateUser(editingUser.id, formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to update user');
            }
        } else {
            const res = await createUser(formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to create user');
            }
        }
    };

    const togglePermission = (key: string) => {
        setSelectedPermissions(prev =>
            prev.includes(key)
                ? prev.filter(p => p !== key)
                : [...prev, key]
        );
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold">Team Management</h1>
                    <p className="text-muted-foreground">Manage employees, salespersons, and accountants.</p>
                </div>
                <button
                    onClick={openCreateModal}
                    className="flex items-center gap-2 bg-primary text-primary-foreground px-4 py-2 rounded-lg hover:opacity-90 transition-opacity"
                >
                    <UserPlus size={20} />
                    Add Member
                </button>
            </div>

            {/* Role Legend */}
            <div className="flex flex-wrap gap-2">
                {Object.entries(ROLE_COLORS).map(([role, color]) => (
                    <span key={role} className={`text-xs px-2 py-1 rounded-full border ${color}`}>
                        {role}
                    </span>
                ))}
            </div>

            <div className="bg-card rounded-xl border border-border overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-secondary/50">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-sm">Employee</th>
                            <th className="px-6 py-4 font-semibold text-sm">Contact</th>
                            <th className="px-6 py-4 font-semibold text-sm">Role</th>
                            <th className="px-6 py-4 font-semibold text-sm">Joined</th>
                            <th className="px-6 py-4 font-semibold text-sm text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {isLoading ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-8 text-center text-muted-foreground">Loading...</td>
                            </tr>
                        ) : users.map((user) => (
                            <tr key={user.id} className="hover:bg-secondary/20 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold ${user.role === 'ROOT' ? 'bg-purple-500' :
                                            user.role === 'ADMIN' ? 'bg-blue-500' :
                                                user.role === 'ACCOUNTANT' ? 'bg-green-500' :
                                                    user.role === 'SALESPERSON' ? 'bg-orange-500' :
                                                        'bg-gray-500'
                                            }`}>
                                            {(user.name || user.username)[0].toUpperCase()}
                                        </div>
                                        <div>
                                            <div className="font-medium">{user.name || 'Anonymous'}</div>
                                            <div className="text-xs text-muted-foreground">@{user.username}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="space-y-1">
                                        {user.phone && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <Phone size={12} /> {user.phone}
                                            </div>
                                        )}
                                        {user.address && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <MapPin size={12} /> {user.address}
                                            </div>
                                        )}
                                        {!user.phone && !user.address && (
                                            <span className="text-xs text-muted-foreground">-</span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium border ${ROLE_COLORS[user.role] || ROLE_COLORS.READ_ONLY}`}>
                                        <Shield size={12} />
                                        {user.role}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-sm text-muted-foreground">
                                    {new Date(user.createdAt).toLocaleDateString()}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-2">
                                        <Link prefetch={false}
                                            href={`/logs?user=${user.id}`}
                                            className="p-2 text-muted-foreground hover:text-blue-500 transition-colors"
                                            title="View Activity"
                                        >
                                            <Eye size={18} />
                                        </Link>
                                        {user.role !== 'ROOT' && (
                                            <>
                                                <button
                                                    onClick={() => openEditModal(user)}
                                                    className="p-2 text-muted-foreground hover:text-primary transition-colors"
                                                    title="Edit"
                                                >
                                                    <Settings size={18} />
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(user.id)}
                                                    className="p-2 text-muted-foreground hover:text-red-500 transition-colors"
                                                    title="Delete"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Create/Edit User Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-card w-full max-w-lg max-h-[90vh] overflow-y-auto p-6 rounded-2xl shadow-xl border border-border">
                        <h2 className="text-xl font-bold mb-4">
                            {editingUser ? 'Edit Team Member' : 'Add Team Member'}
                        </h2>
                        {error && (
                            <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4 text-sm">
                                {error}
                            </div>
                        )}
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Full Name</label>
                                    <input
                                        name="name"
                                        type="text"
                                        defaultValue={editingUser?.name || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="John Doe"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Username</label>
                                    <input
                                        name="username"
                                        type="text"
                                        defaultValue={editingUser?.username || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="johndoe"
                                        disabled={!!editingUser}
                                    />
                                </div>
                            </div>

                            {!editingUser && (
                                <>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Email Address</label>
                                        <input name="email" type="email" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="john@coffee.com" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Password</label>
                                        <input name="password" type="password" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="••••••••" minLength={6} />
                                    </div>
                                </>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Phone</label>
                                    <input
                                        name="phone"
                                        type="tel"
                                        defaultValue={editingUser?.phone || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="01xxxxxxxxx"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Address</label>
                                    <input
                                        name="address"
                                        type="text"
                                        defaultValue={editingUser?.address || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="Cairo, Egypt"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium">Role</label>
                                <select
                                    name="role"
                                    value={selectedRole}
                                    onChange={(e) => setSelectedRole(e.target.value)}
                                    className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                >
                                    <option value="SALESPERSON">Salesperson (Carrier)</option>
                                    <option value="ACCOUNTANT">Accountant</option>
                                    <option value="ADMIN">Admin</option>
                                    <option value="READ_ONLY">Read Only</option>
                                </select>
                                <p className="text-[10px] text-muted-foreground italic">ROOT role can only be assigned via database.</p>
                            </div>

                            {/* Permissions Section */}
                            <div className="space-y-3 p-4 bg-secondary/30 rounded-xl border border-border">
                                <div className="flex items-center justify-between">
                                    <label className="text-sm font-bold">Page Permissions</label>
                                    <label className="flex items-center gap-2 text-xs">
                                        <input
                                            type="checkbox"
                                            checked={useCustomPermissions}
                                            onChange={(e) => setUseCustomPermissions(e.target.checked)}
                                            className="rounded"
                                        />
                                        Custom permissions
                                    </label>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    {ALL_PERMISSIONS.map(perm => (
                                        <label
                                            key={perm.key}
                                            className={`flex items-center gap-2 text-sm p-2 rounded-lg cursor-pointer transition-colors ${selectedPermissions.includes(perm.key)
                                                ? 'bg-primary/10 text-primary'
                                                : 'bg-secondary/50 text-muted-foreground'
                                                } ${!useCustomPermissions ? 'opacity-60' : ''}`}
                                        >
                                            <input
                                                type="checkbox"
                                                checked={selectedPermissions.includes(perm.key)}
                                                onChange={() => togglePermission(perm.key)}
                                                disabled={!useCustomPermissions}
                                                className="rounded"
                                            />
                                            {perm.label}
                                        </label>
                                    ))}
                                </div>
                                {!useCustomPermissions && (
                                    <p className="text-[10px] text-muted-foreground">Using default permissions for {selectedRole} role.</p>
                                )}
                            </div>

                            <div className="flex gap-3 pt-4">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2.5 rounded-lg border border-border hover:bg-secondary transition-colors">Cancel</button>
                                <button type="submit" className="flex-1 bg-primary text-primary-foreground px-4 py-2.5 rounded-lg hover:opacity-90 transition-opacity">
                                    {editingUser ? 'Update' : 'Create'} User
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use server';

import getPrisma from '@/lib/prisma';


interface DateRange {
    startDate?: string;
    endDate?: string;
}

export async function getBuyerReport({ startDate, endDate }: DateRange) {
    const prisma = getPrisma();
    const whereInvoice: any = {};
    const whereRefund: any = {};

    if (startDate && endDate) {
        const dateRange = {
            gte: new Date(startDate),
            lte: new Date(new Date(endDate).setHours(23, 59, 59))
        };
        whereInvoice.date = dateRange;
        whereRefund.createdAt = dateRange;
    }

    const [invoices, refunds] = await Promise.all([
        prisma.invoice.findMany({
            where: whereInvoice,
            select: {
                id: true,
                customerName: true,
                customerPhone: true,
                customerAddress: true,
                totalAmount: true,
                date: true,
                items: true
            },
            orderBy: { date: 'desc' }
        }),
        prisma.refund.findMany({
            where: whereRefund,
            include: {
                items: true,
                invoice: true
            }
        })
    ]);

    // Build product name lookup
    const products = await prisma.product.findMany({ select: { id: true, name: true } });
    const productNameMap = new Map(products.map(p => [p.id, p.name]));

    // Aggregate by Customer (Name + Phone as key)
    const buyerMap = new Map();

    invoices.forEach(inv => {
        const key = `${inv.customerName || 'Unknown'}-${inv.customerPhone || ''}`;
        if (!buyerMap.has(key)) {
            buyerMap.set(key, {
                name: inv.customerName || 'Unknown',
                phone: inv.customerPhone || 'N/A',
                address: inv.customerAddress || '',
                totalSpent: 0,
                visitCount: 0,
                lastVisit: inv.date,
                purchaseHistory: new Map()
            });
        }
        const buyer = buyerMap.get(key);
        buyer.totalSpent += Number(inv.totalAmount);
        buyer.visitCount += 1;
        if (!buyer.address && inv.customerAddress) buyer.address = inv.customerAddress;
        if (new Date(inv.date) > new Date(buyer.lastVisit)) {
            buyer.lastVisit = inv.date;
        }
        // Aggregate purchase history
        const items = inv.items as any[];
        if (Array.isArray(items)) {
            items.forEach(item => {
                const pName = productNameMap.get(item.productId) || item.name || 'Unknown';
                const existing = buyer.purchaseHistory.get(pName) || 0;
                buyer.purchaseHistory.set(pName, existing + (Number(item.quantity) || 0));
            });
        }
    });

    // Subtract Refunds from Buyers
    refunds.forEach(ref => {
        const name = ref.invoice?.customerName || 'Unknown';
        const phone = ref.invoice?.customerPhone || 'N/A';
        const key = `${name}-${phone === 'N/A' ? '' : phone}`;

        const buyer = buyerMap.get(key);
        if (buyer) {
            buyer.totalSpent -= Number(ref.totalAmount);
            // We don't necessarily subtract visitCount unless we consider refund a "negative visit"
            // But we should subtract quantities from purchase history
            ref.items.forEach((item: any) => {
                const pName = productNameMap.get(item.productId) || 'Unknown';
                const existing = buyer.purchaseHistory.get(pName) || 0;
                buyer.purchaseHistory.set(pName, Math.max(0, existing - (Number(item.quantity) || 0)));
            });
        }
    });

    return Array.from(buyerMap.values()).map(b => ({
        ...b,
        purchaseHistory: Array.from(b.purchaseHistory.entries() as IterableIterator<[string, number]>).map(([name, qty]) => ({ name, quantity: qty })).sort((a, b) => b.quantity - a.quantity)
    })).sort((a, b) => b.totalSpent - a.totalSpent);
}

export async function getProductReport({ startDate, endDate }: DateRange) {
    const prisma = getPrisma();
    const whereInvoice: any = {};
    const whereRefund: any = {};

    if (startDate && endDate) {
        const dateRange = {
            gte: new Date(startDate),
            lte: new Date(new Date(endDate).setHours(23, 59, 59))
        };
        whereInvoice.date = dateRange;
        whereRefund.createdAt = dateRange;
    }

    const [invoices, refunds] = await Promise.all([
        prisma.invoice.findMany({
            where: whereInvoice,
            select: { items: true }
        }),
        prisma.refund.findMany({
            where: whereRefund,
            include: { items: true }
        })
    ]);

    const productMap = new Map();
    const products = await prisma.product.findMany({ select: { id: true, name: true, sku: true } });
    const productInfoMap = new Map(products.map(p => [p.id, p]));

    const processItem = (item: any, multiplier: number) => {
        const pId = item.productId;
        if (!productMap.has(pId)) {
            const info = productInfoMap.get(pId);
            productMap.set(pId, {
                id: pId,
                name: info?.name || item.name || 'Unknown Product',
                sku: info?.sku || 'N/A',
                quantitySold: 0,
                revenue: 0
            });
        }
        const stat = productMap.get(pId);
        const qty = (Number(item.quantity) || 0) * multiplier;
        stat.quantitySold += qty;
        const lineTotal = (Number(item.unitPrice || item.price) * (Number(item.quantity) || 0)) * multiplier;
        stat.revenue += lineTotal;
    };

    invoices.forEach(inv => {
        const items = inv.items as any[];
        if (Array.isArray(items)) items.forEach(item => processItem(item, 1));
    });

    refunds.forEach(ref => {
        ref.items.forEach(item => processItem(item, -1));
    });

    return Array.from(productMap.values()).sort((a, b) => b.quantitySold - a.quantitySold);
}

async function getCustomerAnalytics() {
    const prisma = getPrisma();
    
    const customers = await prisma.customer.findMany({
        include: {
            invoices: {
                include: {
                    items: {
                        include: {
                            product: true
                        }
                    }
                }
            }
        },
        orderBy: { name: 'asc' }
    });

    return customers.map(c => {
        let totalSpent = 0;
        let lastVisit: Date | null = null;
        const purchaseHistory = new Map<string, number>();

        c.invoices.forEach(inv => {
            totalSpent += Number(inv.totalAmount);
            if (!lastVisit || new Date(inv.date) > new Date(lastVisit)) {
                lastVisit = inv.date;
            }
            inv.items.forEach(item => {
                const existing = purchaseHistory.get(item.product.name) || 0;
                purchaseHistory.set(item.product.name, existing + item.quantity);
            });
        });

        return {
            id: c.id,
            name: c.name,
            phone: c.phone || 'N/A',
            address: c.address || 'N/A',
            balance: Number(c.balance),
            totalSpent,
            visitCount: c.invoices.length,
            lastVisit,
            purchaseHistory: Array.from(purchaseHistory.entries())
                .map(([name, quantity]) => ({ name, quantity }))
                .sort((a, b) => b.quantity - a.quantity)
        };
    }).sort((a, b) => b.totalSpent - a.totalSpent);
}

