// Get sales details for a specific staff member by period
export async function getStaffSalesDetail(
    userId: string,
    period: 'day' | 'week' | 'month' | '2months' | '6months' | 'all'
) {
    const prisma = getPrisma();

    const now = new Date();
    let startDate: Date | undefined;

    switch (period) {
        case 'day':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            break;
        case 'week':
            startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            break;
        case 'month':
            startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            break;
        case '2months':
            startDate = new Date(now.getFullYear(), now.getMonth() - 2, 1);
            break;
        case '6months':
            startDate = new Date(now.getFullYear(), now.getMonth() - 6, 1);
            break;
        case 'all':
        default:
            startDate = undefined;
    }

    const invoices = await prisma.invoice.findMany({
        where: {
            userId,
            ...(startDate && { date: { gte: startDate } })
        },
        include: {
            items: {
                include: { product: true }
            }
        },
        orderBy: { date: 'desc' }
    });

    const totalSales = invoices.reduce((sum, inv) => sum + Number(inv.totalAmount), 0);
    const totalTransactions = invoices.length;

    return {
        invoices,
        totalSales,
        totalTransactions,
        period
    };
}

'use server';

import getPrisma from '@/lib/prisma';

export async function getStockMovements(
    page = 1,
    limit = 50,
    filters?: {
        type?: string;
        productId?: string;
        locationId?: string;
        startDate?: string;
        endDate?: string;
    }
) {
    const prisma = getPrisma();
    const skip = (page - 1) * limit;

    try {
        const whereClause: any = {};
        if (filters?.type && filters.type !== 'ALL') whereClause.type = filters.type;
        if (filters?.locationId && filters.locationId !== 'ALL') {
            // Check both from and to locations
            whereClause.OR = [
                { fromLocationId: filters.locationId },
                { toLocationId: filters.locationId }
            ];
        }
        // Product filter is trickier because it's a relation on items
        if (filters?.productId && filters.productId !== 'ALL') {
            whereClause.items = {
                some: { productId: filters.productId }
            };
        }
        // Date range filter
        if (filters?.startDate || filters?.endDate) {
            whereClause.date = {};
            if (filters.startDate) whereClause.date.gte = new Date(filters.startDate);
            if (filters.endDate) whereClause.date.lte = new Date(new Date(filters.endDate).setHours(23, 59, 59));
        }

        const [movements, total] = await Promise.all([
            prisma.transaction.findMany({
                where: whereClause,
                skip,
                take: limit,
                orderBy: { date: 'desc' },
                include: {
                    fromLocation: true,
                    toLocation: true,
                    items: {
                        include: {
                            product: { select: { name: true, sku: true } }
                        }
                    },
                    // @ts-ignore: Prisma client type generation lag
                    supplier: true
                }
            }),
            prisma.transaction.count({ where: whereClause })
        ]);

        return {
            success: true,
            movements,
            pagination: {
                total,
                pages: Math.ceil(total / limit),
                current: page
            }
        };
    } catch (error) {
        console.error('Get stock movements error:', error);
        return { success: false, error: 'Failed to fetch stock movements' };
    }
}

